(window.__EXP=window.__EXP||[])[4]="\",\"h10\":\"data:image/webp;base64,\",\"fork\":\"data:image/webp;base64,\",\"storm\":\"data:image/webp;base64,\",\"brief\":\"data:image/webp;base64,\",\"arrival\":\"data:image/webp;base64,\",\"qIdle\":\"data:image/webp;base64,\",\"qListen\":\"data:image/webp;base64,\",\"qTalk\":\"data:image/webp;base64,\",\"qInspect\":\"data:image/webp;base64,\",\"qStorm\":\"data:image/webp;base64,\",\"qCarry\":\"data:image/webp;base64,\",\"nIdle\":\"data:image/webp;base64,\",\"nPoint\":\"data:image/webp;base64,\",\"nStorm\":\"data:image/webp;base64,\",\"mIdle\":\"data:image/webp;base64,\",\"mStop\":\"data:image/webp;base64,\",\"mAid\":\"data:image/webp;base64,\",\"ropeWorn\":\"data:image/webp;base64,\",\"rope\":\"data:image/webp;base64,\",\"frozen\":\"data:image/webp;base64,\",\"water\":\"data:image/webp;base64,\",\"compass\":\"data:image/webp;base64,\",\"map\":\"data:image/webp;base64,\",\"marker\":\"data:image/webp;base64,\",\"shelter\":\"data:image/webp;base64,\",\"aid\":\"data:image/webp;base64,\",\"crate\":\"data:image/webp;base64,\",\"crateWet\":\"data:image/webp;base64,\",\"rubble\":\"data:image/webp;base64,\",\"cloudFx\":\"data:image/webp;base64,\",\"snowFx\":\"data:image/webp;base64,\",\"sandFx\":\"data:image/webp;base64,\",\"rockFx\":\"data:image/webp;base64,\"};\n/* Read the existing route, weather and card state to select presentation art. */\nfunction storyboardPlate(defaultArt){\n  const scene=RUN.scene, place=$(\"#world\").dataset.storyCast;\n  let key=\"\";\n  if(place===\"mountain\"){\n    if(scene===\"M6\"){\n      const h=RUN.hr;\n      if(h&&!h.done){\n        const hazard=HAZARDS[HZ_ROUND[h.i]];\n        const choice=h.res[h.i]?.choice;\n        key=hazard.n===2&&choice===\"FIX\"?\"blocked\"\n          :hazard.n===7&&choice===\"DEFER\"?\"detour\":\"h\"+hazard.n;\n      }\n    } else if($(\"#advScene\").dataset.storyWeather===\"whiteout\"){\n      key=scene===\"M5\"&&RUN.mDec2===\"FIX\"&&RUN.shelterUp?\"sheltered\":\"whiteout\";\n    } else {\n      key=RUN.mDec===\"DEFER\"&&[\"M2out\",\"M3\"].includes(scene)?\"detour\":\"blocked\";\n    }\n  } else if(place===\"desert\"){\n    key=[\"D4\",\"D5\"].includes(scene)?\"brief\":scene===\"D3\"?\"storm\":\"fork\";\n  } else if(place===\"arrival\")key=\"arrival\";\n  return {url:EXPEDITION_ART[key]||defaultArt,key};\n}\nfunction paintStoryPlate(){\n  const scene=$(\"#advScene\"), img=$(\"#advImg\");\n  if(!scene.classList.contains(\"storyPlate\")||!img._storyBase)return;\n  if([\"D4\",\"D5\"].includes(RUN.scene)&&scene.dataset.storyWeather===\"sandstorm\"){\n    scene.dataset.storyWeather=\"\";\n    scene.querySelector(\"#sbSand\")?.remove();\n  }\n  const {url,key}=storyboardPlate(img._storyBase);\n  scene.dataset.art=key;\n  if(img.dataset.sb===url&&img.style.backgroundImage!==\"\")return;\n  img.dataset.sb=url;\n  img.style.backgroundImage=`url(${url})`;\n  img._storyMotion?.cancel();\n  if(S.motion&&img.animate){\n    img._storyMotion=img.animate([{opacity:.74},{opacity:1}],{duration:260,easing:\"ease-out\"});\n  }\n}\nfunction paintHazardProps(){\n  const stage=$(\"#advScene\");\n  if(!stage.classList.contains(\"storyPlate\"))return;\n  let props=[];\n  if(RUN.scene===\"M6\"&&RUN.hr&&!RUN.hr.done){\n    const {i,res}=RUN.hr, n=HAZARDS[HZ_ROUND[i]].n;\n    if(n===2&&res[i]?.choice===\"FIX\")props.push([\"rope\",48,80,17]);\n    if(n===9){\n      props.push([\"map\",62,80,17]);\n      if(res[i]?.choice===\"FIX\")props.push([\"compass\",69,80,8]);\n    }\n  }\n  if(RUN.scene===\"D1\"&&RUN.dev?.water)props.push([\"water\",63,76,10]);\n  const host=$(\"#advLayers\");\n  const live=new Map([...host.querySelectorAll(\"[data-card-prop]\")].map(node=>[node.dataset.cardProp,node]));\n  for(const [key,x,y,width] of props){\n    const old=live.get(key);\n    live.delete(key);\n    if(old)continue;\n    const node=new Image();\n    node.className=\"advLayer\";\n    node.alt=\"\";\n    node.dataset.cardProp=key;\n    node.dataset.layer=\"card-prop-\"+key;\n    node.src=EXPEDITION_ART[key];\n    Object.assign(node.style,{left:x+\"%\",top:y+\"%\",width:width+\"%\",zIndex:5});\n    host.append(node);\n  }\n  live.forEach(node=>node.remove());\n}\nfunction storyRockDust(){\n  if(!S.motion)return;\n  const node=document.createElement(\"div\");\n  node.className=\"expRockDust\";\n  node.setAttribute(\"aria-hidden\",\"true\");\n  node.addEventListener(\"animationend\",()=>node.remove(),{once:true});\n  $(\"#advScene\").append(node);\n}\nfunction refreshSpeechSpace(){\n  const world=$(\"#world\"), wrap=$(\"#vcWrap\"), castBand=$(\"#castBub\");\n  const height=wrap.classList.contains(\"on\")?$(\"#vcBar\").offsetHeight\n    :castBand.classList.contains(\"show\")?castBand.offsetHeight:0;\n  const next=height+\"px\";\n  if(world.style.getPropertyValue(\"--spokenSpace\")!==next)world.style.setProperty(\"--spokenSpace\",next);\n}\nfunction initPresentationArt(){\n  const style=document.documentElement.style;\n  for(const [variable,key] of Object.entries({expeditionCloud:\"cloudFx\",expeditionSnow:\"snowFx\",expeditionSand:\"sandFx\",expeditionRock:\"rockFx\"})){\n    style.setProperty(\"--\"+variable,`url(${EXPEDITION_ART[key]})`);\n  }\n  const band=$(\"#castBub\"), wrap=$(\"#vcWrap\");\n  const observe=new MutationObserver(refreshSpeechSpace);\n  observe.observe(band,{attributes:true,attributeFilter:[\"class\"]});\n  observe.observe(wrap,{attributes:true,attributeFilter:[\"class\"]});\n  if(window.ResizeObserver){\n    const resize=new ResizeObserver(refreshSpeechSpace);\n    resize.observe($(\"#vcBar\"));resize.observe(band);\n  }\n}\n/* Guidance points to existing choices. It never selects or submits a decision. */\nfunction stepAssist(){\n  if(!RUN.scene||![\"jungle\",\"mountain\",\"desert\",\"arrival\"].includes(RUN.stage))return;\n  const panel=$(\"#panelA\");\n  const waiting=RUN.scene===\"J4wait\"||RUN.scene===\"D3wait\";\n  if(S.mode===\"trainer\"&&!waiting)return;\n  const blocked=CF.pending&&S.mode!==\"trainer\"&&panel.querySelector(\".bcActs\");\n  const help=document.createElement(\"div\");\n  help.className=\"expStepAssist\"+(blocked?\" waiting\":\"\");\n  const button=document.createElement(\"button\");\n  button.className=\"btn\";\n  button.type=\"button\";\n  button.textContent=blocked?\"Find objection options \u2193\":\"Show next step \u2193\";\n  button.addEventListener(\"click\",()=>{\n    const sceneOptions=!blocked&&((RUN.scene===\"D2\"&&!RUN.route)||(RUN.scene===\"J3\"&&gearHeld))\n      ?[...document.querySelectorAll(\"#advLayers .dropZone\")].filter(node=>!node.disabled&&node.getClientRects().length):[];\n    let target=blocked||null;\n    if(sceneOptions.length){\n      document.querySelectorAll(\".expStepTarget\").forEach(node=>node.classList.remove(\"expStepTarget\",\"expStepChoices\"));\n      sceneOptions.forEach(node=>node.classList.add(\"expStepTarget\"));\n      sceneOptions[0].scrollIntoView({block:\"nearest\",inline:\"nearest\"});\n      return;\n    }\n    if(!target&&waiting){\n      target=document.querySelector(RUN.scene===\"J4wait\"?\"#jReveal\":\"#dRevealBtn\")\n        ||panel.querySelector(\".gWait + button\")||document.querySelector('[data-mode=\"split\"]');\n    }\n    if(!target){\n      const situation=RUN.scene;\n      const choices={\n        J0:[\"#invNext\",\"#invTyped\",\".invList\"], J1:[\"#jInspectCamp\"], J2:[\".askRow\",\"#jToPreps\"], J2peg:[\"#jPegNote\"],\n        J3:RUN.preps.length===2?[\"#jOpenRisk\",\"#jLock\"]:gearHeld?[\"#advLayers .dropZone\"]:[\".gearTray\"],\n        J4:[\"#jFixRope\",\"#jFixVar\",\"#jToMountain\"],\n        M1:[\"#mOpenRisk\",\".askRow\"],\n        M2:RUN.riskRecorded?[\"#mDecGo\",\".choice\"]:[\"#mRecord\",\".hmGrid\"],\n        M2out:[\"#mToMarker\"], M3:[\"#mReady\",\"#advLayers .dropZone\",\".askRow\"],\n        M4:RUN.risk2Recorded?[\"#mDec2Go\",\".choice\"]:[\"#mRecord2\",\".hmGrid\"],\n        M5:[\"#mRecover\",\"#mSupport\",\"#mToRound\"],M6:[\"#hrNext\",\"#mToDesert\",\".choice\"],\n        D1:[\"#dToRoute\",\".askRow\"], D2:[\"#dExpect:placeholder-shown\",\"#dSign:placeholder-shown\",\"#dLockRoute\"],\n        D3:[\"#dConfirmRoute\",\".routeBtns\"], D4:[\"#dS:placeholder-shown\",\"#dB:placeholder-shown\",\"#dA:placeholder-shown\",\"#dR:placeholder-shown\",\"#dSend\"],\n        D5:[\"#dAskAgain\",\"#dMove\",\".askRow\"], E1:[\"#dReview\"], E2:[\"#dHome\"]\n      }[situation]||[];\n      for(const sel of choices){\n        const exact=sel.startsWith(\"#advLayers\")?document:panel;\n        target=[...exact.querySelectorAll(sel)].find(node=>!node.disabled&&node.getClientRects().length);\n        if(target)break;\n      }\n    }\n    if(!target)return;\n    document.querySelectorAll(\".expStepTarget\").forEach(node=>node.classList.remove(\"expStepTarget\",\"expStepChoices\"));\n    if(blocked){\n      target.closest(\".blockCard\")?.classList.add(\"expStepTarget\",\"expStepChoices\");\n      target.setAttribute(\"tabindex\",\"-1\");\n    } else target.classList.add(\"expStepTarget\");\n    target.scrollIntoView({block:\"center\",inline:\"nearest\",behavior:S.motion?\"smooth\":\"instant\"});\n    if(target.matches(\"button, textarea, input, [tabindex]\"))target.focus({preventScroll:true});\n  });\n  help.append(button);\n  panel.prepend(help);\n}\n\nfunction sbScene(url,layers,cast=\"close\",weather=\"\"){\n  const scene=$(\"#advScene\"), img=$(\"#advImg\"), world=$(\"#world\"), host=$(\"#advLayers\");\n  if(!scene||!img||!host)return;\n  scene.classList.remove(\"hidden\");\n  scene.classList.add(\"storyPlate\");\n  scene.dataset.storyWeather=weather;\n  world.dataset.storyCast=cast;\n  world.classList.add(\"storyDecor\");\n  img._storyBase=url;\n  paintStoryPlate();\n  for(const id of [\"sbRain\",\"sbSnow\",\"sbSand\"]){\n    const keep={sbRain:\"rain\",sbSnow:\"whiteout\",sbSand:\"sandstorm\"}[id];\n    if(keep!==weather)scene.querySelector(\"#\"+id)?.remove();\n  }\n  const current=new Map();\n  for(const node of [...host.children]){\n    if(node.matches(\"img.advLayer\"))current.set(node.dataset.layer,node);\n    else node.remove();\n  }\n  for(const L of layers||[]){\n    const node=current.get(L.id)||document.createElement(\"img\");\n    current.delete(L.id);\n    node.classList.add(\"advLayer\");\n    node.classList.toggle(\"evCard\",!!L.card);\n    node.alt=\"\";\n    node.dataset.layer=L.id;\n    node.toggleAttribute(\"data-detail\",!!L.detail||L.id===\"wet\"||L.id===\"fail\"||(!!L.card&&cast!==\"desert\"));\n    if(node.getAttribute(\"src\")!==L.src)node.src=L.src;\n    Object.assign(node.style,{left:L.x+\"%\",top:L.y+\"%\",width:L.w+\"%\",zIndex:L.z||\"\"});\n    host.append(node);\n  }\n  for(const node of current.values())node.remove();\n  paintStoryCast();\n}\n/* These poses read the rendered scene; they never update expedition state. */\nfunction paintStoryCast(){\n  const world=$(\"#world\"), stage=$(\"#advScene\"), cast=$(\"#stageCast\");\n  const place=world.dataset.storyCast;\n  if(!place||stage.classList.contains(\"hidden\"))return;\n  cast.classList.toggle(\"hidden\",place===\"close\");\n  if(place===\"close\")return;\n  const speaker=sbCurrent?.who, storm=!!stage.dataset.storyWeather;\n  const h=RUN.hr;\n  const givingAid=(RUN.scene===\"M2out\"&&RUN.injured)\n    ||(RUN.scene===\"M6\"&&h&&!h.done&&HAZARDS[HZ_ROUND[h.i]].n===10&&h.res[h.i]?.choice===\"FIX\");\n  const poses={\n    N:storm?\"nStorm\":speaker===\"Navigator\"&&place!==\"travel\"?\"nPoint\":\"nIdle\",\n    M:givingAid?\"mAid\":storm||CF.pending?.by===\"Medic\"?\"mStop\":\"mIdle\",\n    Q:place===\"travel\"?\"qCarry\":storm?\"qStorm\":speaker===\"Quartermaster\"\n      ?[\"J3\",\"J4wait\"].includes(RUN.scene)?\"qInspect\":\"qTalk\":speaker&&speaker!==\"Guide\"?\"qListen\":\"qIdle\"\n  };\n  for(const [id,role] of Object.entries({N:\"Navigator\",M:\"Medic\",Q:\"Quartermaster\"})){\n    const actor=$(\"#cast\"+id), img=actor.querySelector(\"img\");\n    const pose=poses[id], source=EXPEDITION_ART[pose];\n    actor.classList.toggle(\"talk\",speaker===role&&place!==\"travel\");\n    if(img.getAttribute(\"src\")===source)continue;\n    actor._poseMotion?.cancel();\n    img.src=source;\n    img.dataset.storyPose=pose;\n    if(S.motion&&img.animate){\n      actor._poseMotion=img.animate([{opacity:.72},{opacity:1}],{duration:210,easing:\"ease-out\"});\n    }\n  }\n}\nfunction storyFlyGear(src,from,layer){\n  if(!S.motion||!src||!from?.width||!from.height)return;\n  const dest=$(\"#advLayers\").querySelector(`[data-layer=\"${layer}\"]`);\n  if(!dest)return;\n  const to=dest.getBoundingClientRect();\n  if(!to.width||!to.height||!dest.animate)return;\n  const world=$(\"#world\").getBoundingClientRect();\n  if(from.top>=innerHeight||from.bottom<=0||to.top>=world.bottom||to.bottom<=world.top)return;\n  const sprite=document.createElement(\"img\");\n  sprite.src=src;sprite.alt=\"\";sprite.setAttribute(\"aria-hidden\",\"true\");sprite.className=\"storyGearFlight\";\n  Object.assign(sprite.style,{left:from.left+\"px\",top:from.top+\"px\",width:from.width+\"px\",height:from.height+\"px\"});\n  document.body.append(sprite);\n  const dx=to.left+(to.width-from.width)/2-from.left, dy=to.top+(to.height-from.height)/2-from.top;\n  const flight=sprite.animate([\n    {transform:\"translate(0,0)\",opacity:1},\n    {transform:`translate(${dx}px,${dy}px) scale(.78)`,opacity:.12}\n  ],{duration:430,easing:\"cubic-bezier(.19,.68,.28,1)\"});\n  flight.onfinish=flight.oncancel=()=>sprite.remove();\n  dest.animate([{opacity:.78},{opacity:1}],{duration:260,delay:240,easing:\"ease-out\"});\n}\n\n/* ---------------- Jungle panels, J1 to J5 ---------------- */\n/* ---------- supplies round: inventory cards before the camp opens ---------- */\nconst INV_DECK=[0,24,13,28,26];   /* Lantern, Compass, Fuel, Bandages, Tent pegs */\nfunction invState(){ RUN.inv=RUN.inv||{i:0,res:[],hint:false,off:false,typed:\"\",done:false}; return RUN.inv; }\nfunction invNorm(x){ return String(x||\"\").toLowerCase().replace(/[^a-z0-9 ]/g,\" \").replace(/\\s+/g,\" \").trim(); }\nfunction invMatch(it,ans){ const a=invNorm(ans); if(!a)return false;\n  return [it.a].concat(it.alt||[]).some(x=>invNorm(x)===a); }\nfunction invCat(a){ return Object.keys(CHECKLIST).find(c=>CHECKLIST[c].indexOf(a)>=0)||\"\"; }\nfunction invAnswer(ans,el){\n  const iv=invState(); if(iv.res[iv.i])return;\n  const it=INVENTORY[INV_DECK[iv.i]], ok=invMatch(it,ans);\n  iv.res[iv.i]={ok:ok,ans:ans};\n  runLog(\"jungle\",\"Supplies: \"+it.a+(ok?\" found\":\" missed\"),\"Team\");\n  if(ok) addShields(it.x?2:1,(it.x?\"Hidden item found: \":\"Correct item: \")+it.a,el);\n  else { try{SFX.wrong();}catch(e){} }\n  render();\n}\nfunction invPane(){\n  const iv=invState(), n=INV_DECK.length;\n  if(iv.done){\n    const ok=iv.res.filter(r=>r&&r.ok).length;\n    const hid=INV_DECK.map(k=>INVENTORY[k]).filter(it=>it.x);\n    const hidOk=iv.res.filter((r,i)=>r&&r.ok&&INVENTORY[INV_DECK[i]].x).length;\n    return now(\"Supplies checked\",ok+\" of \"+n+\" items found. \"+hidOk+\" of \"+hid.length+\" were never on the checklist.\",\"Next: inspect the camp.\")+\n      `<div class=\"infoBlk\"><b>Not on the checklist</b><p>${hid.map(it=>esc(it.a)).join(\" \u00b7 \")}</p></div>`+\n      skillHTML(\"Observe beyond the checklist\",\"A list only holds what someone thought of. The camp has more of these waiting.\")+\n      `<button class=\"btn primary block\" id=\"invToCamp\" style=\"margin-top:12px\">Inspect the camp</button>`;\n  }\n  const it=INVENTORY[INV_DECK[iv.i]], r=iv.res[iv.i];\n  let b=now(\"Inventory card \"+(iv.i+1)+\" of \"+n,\"Read the clue and find the item. If it is not on the checklist, name it yourself.\",\n      r?\"Next: the next card.\":\"Next: tap an item on the checklist, or name one that is not there.\")+\n    `<div class=\"invCard\"><div class=\"eyebrow\">Clue</div><p>${esc(it.c)}</p>${(iv.hint&&!r)?`<p class=\"small\" style=\"margin-top:6px\">First letter: <b>${esc(it.a[0])}</b></p>`:\"\"}</div>`;\n  if(r){\n    b+=`<div class=\"fbCard ${r.ok?\"right\":\"wrong\"}\"><b>${r.ok?(\"Correct \u2014 \"+esc(it.a)):(\"The answer is \"+esc(it.a))}</b>\n      <p>${it.x?\"This one is not on the checklist. Nobody wrote it down, but the team still needs it.\":\"It is on the checklist under \"+esc(invCat(it.a))+\".\"}${r.ok?\"\":\" You answered: \"+esc(r.ans||\"nothing\")+\".\"}</p>\n      ${r.ok?`<div class=\"cost\">+${it.x?2:1} shield${it.x?\"s\":\"\"}</div>`:\"\"}</div>\n      <button class=\"btn primary block\" id=\"invNext\">${iv.i+1<n?\"Next card\":\"See the supplies\"}</button>`;\n  } else {\n    b+=`<div class=\"invList\">${Object.keys(CHECKLIST).map(c=>`<div class=\"invCat\"><div class=\"eyebrow\">${esc(c)}</div>\n        <div class=\"invChips\">${CHECKLIST[c].map(x=>`<button data-inv=\"${esc(x)}\">${esc(x)}</button>`).join(\"\")}</div></div>`).join(\"\")}</div>\n      ${iv.off?`<label class=\"eyebrow\" style=\"display:block;margin-top:10px\">What is the item?</label>\n        <input class=\"field\" id=\"invTyped\" placeholder=\"Name the item\" value=\"${esc(iv.typed||\"\")}\">\n        <button class=\"btn primary block\" id=\"invCheck\">Check my answer</button>`\n       :`<button class=\"btn block\" id=\"invOff\" style=\"margin-top:10px\">It's not on the checklist</button>`}\n      <button class=\"btn block\" id=\"invHint\" ${iv.hint?\"disabled\":\"\"} style=\"margin-top:8px\">Reveal first letter \u00b7 1 action token</button>`;\n  }\n  return b;\n}\nfunction jPane(){\n  const st=RUN.scene; const v=jVar(); let body=\"\";\n  const shared=id=>!!RUN.evidence[id];\n  if(st===\"J0\"){ body=invPane(); }\n  else if(st===\"J1\"){\n    body=now(\"Inspect before you prepare\",\n      \"The camp is marked ready and rain is coming. You have time for two preparations \u2014 so what you check first decides what you can still fix.\",\n      \"Next: look at what caught your eye.\")+\n      `<button class=\"btn primary block\" id=\"jInspectCamp\">Inspect the camp</button>`;\n  }\n  else if(st===\"J2\"){\n    const rope=shared(\"rope\"), peg=shared(\"peg\"), vv=shared(v.ev);\n    body=now(\"Each team turns up something different\",\n      \"Three sets of eyes, three different things to look at. Anything you share goes on the board for the whole team.\",\n      (rope&&peg&&vv)?\"Next: agree on two preparations.\":\"Next: share what you find.\")+\n      `<div class=\"askRow\">\n        <button data-jchk=\"rope\" ${rope?\"disabled\":\"\"}>Navigator<br><b>Check tent rope</b></button>\n        <button data-jchk=\"peg\" ${(!rope||peg)?\"disabled\":\"\"}>Navigator<br><b>Inspect the peg</b></button>\n        <button data-jchk=\"var\" ${vv?\"disabled\":\"\"}>Medic<br><b>${esc(v.checkBtn)}</b></button>\n      </div>\n      <button class=\"btn block\" id=\"jGear\">Open gear tray</button>`+\n      (evCount()?`<div class=\"hr\"></div><div class=\"eyebrow\">Evidence on the board</div>`+\n        Object.keys(RUN.evidence).map(k=>`<div class=\"logLine\"><b>${esc(RUN.evidence[k].by)}</b><span>${esc(RUN.evidence[k].text)}</span></div>`).join(\"\"):\"\")+\n      `<button class=\"btn primary block\" id=\"jToPreps\" style=\"margin-top:12px\">${\n        (rope&&peg&&vv)?\"Agree on preparations\":\"Skip the checks \u2014 the checklist says we are ready\"}</button>`;\n  }\n  else if(st===\"J2peg\"){\n    body=now(\"What changed at the anchor point?\",\n      \"One close look at the peg and the ground around it. Nothing else moves while you are down here.\",\n      \"Next: record it, or go back to the camp.\")+\n      `<textarea class=\"field\" id=\"jPegNote\" placeholder=\"What changed at the anchor point?\">${esc(RUN.pegNote||\"\")}</textarea>\n       <button class=\"btn primary block\" id=\"jPegRec\">Record observation</button>\n       <button class=\"btn block\" id=\"jPegBack\">Back to camp</button>`;\n  }\n  else if(st===\"J3\"){\n    const picked=RUN.preps;\n    body=now(\"Two preparations, one risk left open\",\n      \"The Quartermaster can set up two of these before the rain. Whatever you leave out is the thing the rain will find.\",\n      picked.length<2?`Next: choose ${2-picked.length} more.`:\"Next: name the risk you are leaving open.\")+\n      gearTrayHTML()+\n      cfBlockCard()+\n      `<p class=\"small dim\" style=\"margin-top:8px\">${picked.length?(\"Placed: \"+picked.map(k=>esc(JUNGLE_PREPS[k].label)).join(\" \u00b7 \")):\"Nothing placed yet.\"}</p>`+\n      ((picked.length===2&&!CF.pending)?`<label class=\"eyebrow\" style=\"display:block;margin-top:12px\">Which risk are you leaving open?</label>\n         <input class=\"field\" id=\"jOpenRisk\" value=\"${esc(RUN.openRisk||\"\")}\" placeholder=\"Name it in your own words\">\n         <button class=\"btn primary block\" id=\"jLock\">Lock preparations</button>`:\"\");\n  }\n  else if(st===\"J4wait\"){\n    body=now(\"Preparations locked\",\"The two preparations are in place. The rain decides the rest.\",\n      \"Next: the facilitator reveals the rain.\")+\n      `<div class=\"infoBlk\"><b>Locked</b><p>${RUN.preps.map(k=>esc(JUNGLE_PREPS[k].done)).join(\" \")}</p>\n       <p class=\"small dim\">Left open: ${esc(RUN.openRisk||\"not named\")}</p></div>`;\n  }\n  else if(st===\"J4\"){\n    const out=jOutcome();\n    const left=jRepairsLeft();\n    const fixBtn=left.indexOf(\"rope\")>=0?[\"jFixRope\",\"Secure the anchor\"]\n              :left.indexOf(\"variant\")>=0?[\"jFixVar\",v.fixBtn]:null;\n    body=now(\"The rain tests the plan\",\n      out===\"clear\"?\"The line is holding and the gear is protected. The team can load.\"\n        :(out===\"rope\"?\"The line let go and that side of the tent came down.\"\n        :(out===\"both\"?(\"The line let go, and \"+v.fail.toLowerCase()):v.fail)),\n      fixBtn?(left.length>1?\"Next: put both right, the anchor first.\":\"Next: put it right.\"):\"Next: carry the crate up.\")+\n      (fixBtn?`<button class=\"btn primary block\" id=\"${fixBtn[0]}\">${esc(fixBtn[1])}</button>`:\"\")+\n      (!fixBtn?`<button class=\"btn primary block\" id=\"jToMountain\">Continue to Mountain Pass</button>`:\"\")+\n      (RUN.bonusPrep?skillHTML(\"Extra mountain preparation earned\",\"Both pieces of evidence were on the board before the rain, so the team carries a spare preparation up the pass.\"):\"\");\n  }\n  const p=document.createElement(\"section\"); p.className=\"pane\";\n  p.innerHTML=`<div class=\"paneHead\"><h3>Participant \u00b7 Team 1</h3><span class=\"badge\">Dense Jungle</span></div>\n    ${guideBar()}${scoreStrip()}${hud()}${body}${fbNoteHTML()}${skipBox()}`;\n  return p;\n}\n\n\n/* ---------------- action sound + reward feedback ---------------- */\nfunction sfxAct(kind){\n  if(!S.sfx)return;\n  const C={\n    rope:()=>{blip(240,.18,\"sawtooth\",.05,120); setTimeout(()=>blip(180,.22,\"sine\",.04,90),90);},\n    snap:()=>{blip(900,.07,\"square\",.07,180); setTimeout(()=>blip(150,.3,\"sine\",.06,70),60);},\n    cloth:()=>{blip(1200,.3,\"sine\",.022,400); setTimeout(()=>blip(800,.26,\"sine\",.02,300),120);},\n    mallet:()=>{blip(160,.1,\"square\",.08,90); setTimeout(()=>blip(150,.1,\"square\",.06,80),180);\n                setTimeout(()=>blip(140,.14,\"square\",.05,70),360);},\n    water:()=>{blip(520,.5,\"sine\",.025,260);},\n    crate:()=>{blip(120,.26,\"sine\",.07,95);},\n    bag:()=>{blip(700,.14,\"triangle\",.035,520);},\n    place:()=>{blip(660,.1,\"triangle\",.05); setTimeout(()=>blip(990,.14,\"sine\",.04),80);},\n    wrong:()=>{blip(300,.16,\"sine\",.045,220);},\n    tap:()=>{blip(520,.06,\"sine\",.035);}\n  };\n  (C[kind]||C.tap)();\n}\n/* a gain or a loss is never silent and never still */\nfunction rewardFx(el,kind,label){\n  if(kind===\"gain\"){ blip(620,.14,\"triangle\",.07); setTimeout(()=>blip(930,.18,\"triangle\",.06),110);\n    setTimeout(()=>blip(1480,.44,\"sine\",.035),220); }\n  else { blip(330,.2,\"sine\",.05,240); setTimeout(()=>blip(240,.3,\"sine\",.045,180),150); }\n  const host=$(\"#ppBurst\");\n  if(host){ host.textContent=label; host.style.background=(kind===\"gain\")\n      ? \"linear-gradient(180deg,#f3dfa7,#c9a44e)\" : \"linear-gradient(180deg,#e9b79b,#b86a4d)\";\n    host.classList.remove(\"show\"); void host.offsetWidth; host.classList.add(\"show\");\n    setTimeout(()=>host.classList.remove(\"show\"),1900); }\n}\n\n/* ---------------- gear tray: drag, tap-tap, keyboard ----------------\n   Each tool has one right place in the frame. Dropping it anywhere else sends\n   it back to the tray with a hint and costs nothing. */\nconst GEAR_SLOT={\n  peg:{zone:\"anchor\", x:21, y:76, w:13, label:\"Anchor point\"},\n  rainfly:{zone:\"roof\", x:36, y:48, w:17, label:\"Tent roof\"},\n  groundsheet:{zone:\"floor\", x:60, y:78, w:16, label:\"Packing area\"}\n};\nlet gearHeld=null;\nfunction gearPick(k){\n  if(RUN.scene!==\"J3\")return;\n  gearHeld=(gearHeld===k)?null:k;\n  sfxAct(\"tap\"); gearPaint(); render();\n}\nfunction gearDrop(zone){\n  if(!gearHeld)return;\n  const k=gearHeld, slot=GEAR_SLOT[k];\n  if(slot.zone!==zone){\n    sfxAct(\"wrong\"); gearHeld=null; gearPaint(); render();\n    toast(JUNGLE_PREPS[k].label+\" belongs at the \"+slot.label.toLowerCase()+\".\");\n    return;\n  }\n  const tile=[...document.querySelectorAll(`[data-gear=\"${k}\"] img`)].find(img=>img.getClientRects().length);\n  const from=tile?.getBoundingClientRect();\n  const added=RUN.preps.indexOf(k)<0;\n  if(added){\n    if(RUN.preps.length>=2){ toast(\"Two preparations only. Take one off first.\"); gearHeld=null; gearPaint(); render(); return; }\n    RUN.preps.push(k); sfxAct(\"place\");\n  }\n  gearHeld=null; jShowCamp(false); gearPaint(); render();\n  if(added)storyFlyGear(tile?.src,from,k===\"peg\"?\"rope\":k===\"groundsheet\"?\"ground\":k);\n}\nfunction gearRemove(k){\n  const i=RUN.preps.indexOf(k);\n  if(i>=0){ RUN.preps.splice(i,1); sfxAct(\"tap\"); jShowCamp(false); gearPaint(); render(); }\n}\n/* the drop zones live on the scene itself */\nfunction gearPaint(){\n  const wld=$(\"#world\"); if(wld) wld.classList.toggle(\"placing\",RUN.scene===\"J3\");\n  const host=$(\"#advLayers\"); if(!host)return;\n  host.querySelectorAll(\".dropZone\").forEach(e=>e.remove());\n  if(RUN.scene!==\"J3\")return;\n  Object.keys(GEAR_SLOT).forEach(k=>{\n    const s=GEAR_SLOT[k];\n    if(RUN.preps.indexOf(k)>=0)return;\n    const z=document.createElement(\"button\");\n    z.className=\"dropZone\"+(gearHeld===k?\" live\":\"\");\n    z.dataset.zone=s.zone;\n    z.style.left=s.x+\"%\"; z.style.top=s.y+\"%\"; z.style.width=s.w+\"%\";\n    z.innerHTML=`<span>${esc(s.label)}</span>`;\n    z.setAttribute(\"aria-label\",\"Place a tool at the \"+s.label);\n    z.onclick=()=>gearDrop(s.zone);\n    z.ondragover=e=>{e.preventDefault();z.classList.add(\"over\");};\n    z.ondragleave=()=>z.classList.remove(\"over\");\n    z.ondrop=e=>{e.preventDefault();z.classList.remove(\"over\");\n      const k2=e.dataTransfer.getData(\"text/plain\"); if(k2)gearHeld=k2; gearDrop(s.zone);};\n    host.appendChild(z);\n  });\n}\nfunction gearTrayHTML(){\n  return `<div class=\"gearTray\" role=\"group\" aria-label=\"Gear tray\">\n    ${Object.keys(JUNGLE_PREPS).map(k=>{\n      const used=RUN.preps.indexOf(k)>=0;\n      return `<button class=\"gearItem${gearHeld===k?\" held\":\"\"}${used?\" used\":\"\"}\" data-gear=\"${k}\"\n        draggable=\"${used?\"false\":\"true\"}\" aria-pressed=\"${gearHeld===k}\">\n        <img src=\"${ADV.items[k===\"groundsheet\"?\"ground\":k]}\" alt=\"\">\n        <b>${esc(JUNGLE_PREPS[k].label)}</b>\n        <small>${used?\"Placed \u00b7 tap to take back\":\"Drag it, or tap then tap the spot\"}</small></button>`;}).join(\"\")}\n  </div>`;\n}\nfunction gearBind(){\n  document.querySelectorAll(\"[data-gear]\").forEach(b=>{\n    const k=b.dataset.gear;\n    b.onclick=()=>{ if(RUN.preps.indexOf(k)>=0) gearRemove(k); else gearPick(k); };\n    b.ondragstart=e=>{ gearHeld=k; e.dataTransfer.setData(\"text/plain\",k); gearPaint(); };\n    b.onkeydown=e=>{ if(e.key===\"Enter\"||e.key===\" \"){ e.preventDefault(); b.click(); } };\n  });\n  gearPaint();\n}\n\n/* ================= Mountain M1..M5 (storyboard) ================= */\nconst MTN_EV={\n  rubble:{by:\"Quartermaster\", t:\"Loose rubble\", note:\"The pile is unstable and shifts when touched\",\n          x:30, y:52, img:\"rubble\"},\n  ledge:{by:\"Medic\", t:\"The ledge\", note:\"Anyone clearing the rocks works right beside the drop\",\n         x:62, y:64, img:\"ledge\"},\n  around:{by:\"Navigator\", t:\"The way around\", note:\"A longer path exists and is still visible\",\n          x:80, y:40, img:\"after\"}\n};\nfunction mPane(){\n  const st=RUN.scene; let body=\"\";\n  const r=RUN.risk||{};\n  if(st===\"M1\"){\n    const n=Object.keys(RUN.mev||{}).length;\n    body=now(\"Read the hazard before you judge it\",\n      \"Rock came down across the trail. Touch what you want to look at \u2014 each team sees a different part of it.\",\n      n<2?\"Next: at least two pieces before the assessment opens.\":\"Next: place it on the risk matrix.\")+\n      (RUN.crate.wet&&!RUN.crateSecured?`<button class=\"btn block\" id=\"mSecure\">Secure the crate for transport</button>`:\"\")+\n      `<div class=\"askRow\">${Object.keys(MTN_EV).map(k=>`<button data-mev=\"${k}\" ${RUN.mev&&RUN.mev[k]?\"disabled\":\"\"}>\n        <b>${esc(MTN_EV[k].t)}</b><small>${esc(MTN_EV[k].by)}</small></button>`).join(\"\")}</div>`+\n      (n?`<div class=\"hr\"></div>`+Object.keys(RUN.mev).map(k=>`<div class=\"logLine\"><b>${esc(MTN_EV[k].by)}</b><span>${esc(MTN_EV[k].note)}</span></div>`).join(\"\"):\"\")+\n      (n>=2?`<button class=\"btn primary block\" id=\"mOpenRisk\" style=\"margin-top:12px\">Open risk assessment</button>`:\"\");\n  }\n  else if(st===\"M2\"){\n    body=now(\"Likelihood and severity\",\n      \"Place the hazard on the matrix from the training material, then choose what to do about it.\",\n      (r.l!=null&&r.s!=null)?\"Next: record it, then fix or defer.\":\"Next: pick a level on each axis.\")+\n      mGrid(\"first\")+\n      `<button class=\"btn primary block\" id=\"mRecord\" ${(r.l!=null&&r.s!=null)?\"\":\"disabled\"}>Record assessment</button>`+\n      (RUN.riskRecorded?`<div class=\"choice\" style=\"margin-top:12px\">\n          <button data-mdec=\"FIX\" aria-pressed=\"${RUN.mDec===\"FIX\"}\">Fix<small>Clear the rocks</small></button>\n          <button data-mdec=\"DEFER\" aria-pressed=\"${RUN.mDec===\"DEFER\"}\">Defer<small>Take the way around</small></button>\n        </div>\n        <button class=\"btn primary block\" id=\"mDecGo\" ${RUN.mDec?\"\":\"disabled\"}>Submit decision</button>`:\"\");\n  }\n  else if(st===\"M2out\"){\n    const fix=(RUN.mDec===\"FIX\");\n    body=now(\"Result \u00b7 Hazard 04\",\n      fix?\"The rocks did not move, and someone was hurt trying. The cost of the attempt stands, and the Medic carries the injury down the pass.\"\n         :\"The team stepped back from the edge and took the marked way around.\",\n      \"Next: set the marker you will navigate by.\")+\n      `<div class=\"fbCard ${fix?\"wrong\":\"right\"}\"><b>${fix?\"The attempt failed.\":\"Hazard avoided.\"}</b>\n        <p>${fix?esc(HAZARDS[3].fix):esc(HAZARDS[3].def)}</p>\n        ${fix?`<div class=\"cost\">Action cost: ${HAZARDS[3].cost} tokens \u2014 from the card, counted once.</div>`:\"\"}</div>\n       <button class=\"btn primary block\" id=\"mToMarker\">Continue</button>`;\n  }\n  else if(st===\"M3\"){\n    body=now(\"Set your own marker\",\n      \"Touch the point on the trail you will navigate by. This is the reference the team will look for.\",\n      RUN.marker?\"Next: prepare what you can carry.\":\"Next: place the marker on the scene.\")+\n      (RUN.marker?`<div class=\"infoBlk\"><b>Marker set</b><p>The team will steer by the point you chose.</p></div>\n        <div class=\"askRow\">\n          <button data-mprep=\"shelter\" ${RUN.shelter?\"disabled\":\"\"}>Prepare shelter</button>\n          <button data-mprep=\"backup\" ${RUN.backup?\"disabled\":\"\"}>Set backup reference</button>\n        </div>\n        <p class=\"small dim\">${RUN.bonusPrep?\"Your jungle preparation lets you do both.\":\"One preparation only on this run.\"}</p>\n        <button class=\"btn primary block\" id=\"mReady\" ${(RUN.shelter||RUN.backup)?\"\":\"disabled\"}>Move out</button>`\n        :`<p class=\"small dim\" style=\"margin-top:8px\">Tap the glowing point on the trail.</p>`);\n  }\n  else if(st===\"M4\"){\n    body=now(\"The marker is gone\",\n      \"Snow came across the trail and took the reference you set with it. The hazard is new, so the reading has to be new too.\",\n      \"Next: reassess, then decide again.\")+\n      mGrid(\"second\")+\n      `<label class=\"eyebrow\" style=\"display:block;margin-top:10px\">What changed in your evidence?</label>\n       <textarea class=\"field\" id=\"mWhy\">${esc(RUN.riskWhy2||\"\")}</textarea>\n       <button class=\"btn primary block\" id=\"mRecord2\" ${(RUN.risk2&&RUN.risk2.l!=null&&RUN.risk2.s!=null)?\"\":\"disabled\"}>Record new assessment</button>`+\n      (RUN.risk2Recorded?`<div class=\"choice\" style=\"margin-top:12px\">\n          <button data-mdec2=\"FIX\" aria-pressed=\"${RUN.mDec2===\"FIX\"}\">Fix<small>Shelter and wait</small></button>\n          <button data-mdec2=\"DEFER\" aria-pressed=\"${RUN.mDec2===\"DEFER\"}\">Defer<small>Keep moving</small></button>\n        </div>\n        <button class=\"btn primary block\" id=\"mDec2Go\" ${RUN.mDec2?\"\":\"disabled\"}>Submit decision</button>`:\"\");\n  }\n  else if(st===\"M6\"){ body=hrPane(); }\n  else if(st===\"M5\"){\n    const fix=(RUN.mDec2===\"FIX\");\n    body=now(\"Result \u00b7 Hazard 08\",\n      fix?(RUN.shelter?\"The shelter you prepared was already up, so the team was under cover at once and waited for the pass to clear.\":\"The team sheltered and waited for the pass to clear.\")\n         :\"Visibility dropped so far that the team drifted off the trail.\",\n      fix?\"Next: down to the desert.\":\"Next: get back to something you can confirm.\")+\n      `<div class=\"fbCard ${fix?\"right\":\"wrong\"}\"><b>${fix?\"Sheltered.\":\"Off the trail.\"}</b>\n        <p>${fix?esc(HAZARDS[7].fix):esc(HAZARDS[7].def)}</p>\n        ${fix?`<div class=\"cost\">Action cost: ${HAZARDS[7].cost} tokens \u2014 from the card, counted once.</div>`:\"\"}</div>`+\n      ((!fix&&!RUN.recovered)\n        ? (RUN.backup?`<button class=\"btn primary block\" id=\"mRecover\">Return to last confirmed point</button>`\n                     :`<button class=\"btn primary block\" id=\"mSupport\">Request support</button>`)\n        : `<button class=\"btn primary block\" id=\"mToRound\">Continue down the pass</button>`)+\n      (RUN.recovered?skillHTML(\"Dynamic adaptation\",\"You lost the trail and used a point you had confirmed earlier to get back on it.\"):\"\");\n  }\n  const p=document.createElement(\"section\"); p.className=\"pane\";\n  p.innerHTML=`<div class=\"paneHead\"><h3>Participant \u00b7 Team 1</h3><span class=\"badge\">Mountain Pass</span></div>\n    ${guideBar()}${scoreStrip()}${hud()}${body}${cfBlockCard()}${fbNoteHTML()}${skipBox()}`;\n  return p;\n}\nfunction mGrid(which){\n  const cur=(which===\"first\")?(RUN.risk||{}):(RUN.risk2||{});\n  const first=RUN.risk||{};\n  let out=`<div class=\"hm\"><div class=\"hmGrid\"><div class=\"hd\"></div>${HM_SD.map(s=>`<div class=\"hd\">${s}</div>`).join(\"\")}`;\n  for(let l=4;l>=0;l--){\n    out+=`<div class=\"hd\">${HM_LD[l]}</div>`;\n    for(let s=0;s<5;s++){\n      const [nm,col]=HM_BAND(l,s);\n      const on=cur.l===l&&cur.s===s;\n      const was=(which===\"second\"&&first.l===l&&first.s===s);\n      out+=`<button data-mrisk=\"${which}\" data-l=\"${l}\" data-s=\"${s}\" aria-pressed=\"${on}\"\n        style=\"background:${col}${was&&!on?\";outline:2px dashed rgba(255,255,255,.7);outline-offset:-3px\":\"\"}\"\n        title=\"${nm}\">${on?nm:(was?\"Before\":\"\")}</button>`;\n    }\n  }\n  out+=`</div>`;\n  if(which===\"second\"&&first.l!=null&&cur.l!=null){\n    const same=(HM_BAND(first.l,first.s)[0]===HM_BAND(cur.l,cur.s)[0]);\n    out+=`<div class=\"hmMark\"><span>Before: ${HM_L[first.l]} \u00d7 ${HM_S[first.s]} \u2014 ${HM_BAND(first.l,first.s)[0]}</span>\n      <span>Now: ${HM_L[cur.l]} \u00d7 ${HM_S[cur.s]} \u2014 ${HM_BAND(cur.l,cur.s)[0]}</span>\n      ${same?`<span>Same rating \u00b7 new evidence recorded</span>`:\"\"}</div>`;\n  }\n  return out+`</div>`;\n}\n\n/* ---------------- Mountain wiring ---------------- */\nfunction mLayers(){\n  const L=[];\n  if(RUN.scene!==\"M6\")\n    L.push({id:\"crate\",src:EXPEDITION_ART[RUN.crate.wet&&!RUN.crateSecured?\"crateWet\":\"crate\"],x:31,y:89,w:10});\n  if(RUN.mev?.rubble&&!RUN.markerLost&&RUN.scene!==\"M6\")\n    L.push({id:\"rubble\",src:EXPEDITION_ART.rubble,x:30,y:74,w:13,z:4});\n  if(RUN.marker&&!RUN.markerLost)\n    L.push({id:\"marker\", src:EXPEDITION_ART.marker, x:RUN.marker.x, y:RUN.marker.y, w:9, z:6});\n  if(RUN.shelterUp&&RUN.scene===\"M3\") L.push({id:\"shelter\", src:EXPEDITION_ART.shelter, x:70, y:83, w:14, z:6});\n  return L;\n}\nfunction mShow(scene,whiteout){\n  sbScene(scene||ADV.scenes.mb, mLayers().filter(layer=>!whiteout||layer.id!==\"shelter\"),\"mountain\",whiteout?\"whiteout\":\"\");\n  const ov=$(\"#advScene\");\n  let s=document.getElementById(\"sbSnow\");\n  if(whiteout&&!s){ s=document.createElement(\"div\"); s.id=\"sbSnow\"; ov.appendChild(s); }\n  if(!whiteout&&s) s.remove();\n}\nfunction mGo(scene){ RUN.scene=scene; rpHush(); render(); }\nfunction mStart(){\n  RUN.stage=\"mountain\"; RUN.scene=\"M1\"; RUN.mev={};\n  cfStage(\"Mountain \u00b7 blocked path\"); S.fbNote=null; rpHush();\n  mShow(ADV.scenes.mb,false);\n  sbSeq([[\"Guide\",\"The trail is blocked. Before you choose what to do, check how likely the danger is and how serious it could be.\"],\n         [\"Navigator\",\"There's another way around. I can mark it on the map.\"],\n         [\"Quartermaster\",\"If we can clear this, we save time. Can we work from here?\"],\n         [\"Medic\",\"Look at the ledge. If someone slips here, the drop matters.\"]]);\n  render();\n}\nfunction mBind(){\n  const on=(s,f)=>document.querySelectorAll(s).forEach(e=>e.onclick=f);\n  on(\"#mSecure\",()=>{ if(!runOnce(\"mSecure\"))return; RUN.crateSecured=true; sfxAct(\"crate\");\n    sbSay(\"Quartermaster\",\"The crate is secured for the climb.\",()=>render()); mShow(ADV.scenes.mb,false); render(); });\n  document.querySelectorAll(\"[data-mev]\").forEach(b=>b.onclick=()=>{\n    const k=b.dataset.mev; RUN.mev=RUN.mev||{}; if(RUN.mev[k])return;\n    RUN.mev[k]=true; sfxAct(\"tap\");\n    perfAward(MTN_EV[k].by,\"evidence\",MTN_EV[k].note);\n    mShow(ADV.scenes.mb,false);\n    sbSay(MTN_EV[k].by,MTN_EV[k].note+\".\",()=>render()); render(); });\n  on(\"#mOpenRisk\",()=>{ sfxAct(\"tap\"); mGo(\"M2\"); });\n  document.querySelectorAll(\"[data-mrisk]\").forEach(b=>b.onclick=()=>{\n    const w=b.dataset.mrisk, v={l:+b.dataset.l,s:+b.dataset.s};\n    if(w===\"first\"){ if(RUN.riskRecorded)return; RUN.risk=v; } else { if(RUN.risk2Recorded)return; RUN.risk2=v; }\n    sfxAct(\"tap\"); render(); });\n  on(\"#mRecord\",()=>{ if(!RUN.risk||RUN.risk.l==null)return; if(!runOnce(\"mRec1\"))return;\n    RUN.riskRecorded=true; SFX.submit();\n    perfAward(\"Medic\",\"evidence\",\"Placed the rockfall on the likelihood and severity matrix\"); render(); });\n  document.querySelectorAll(\"[data-mdec]\").forEach(b=>b.onclick=()=>{RUN.mDec=b.dataset.mdec;sfxAct(\"tap\");render();});\n  on(\"#mDecGo\",()=>{ if(!RUN.mDec||CF.pending)return;\n    /* clearing the rocks puts someone beside the drop: the Medic can stop it, once */\n    if(RUN.mDec===\"FIX\"&&!RUN.mObj){ RUN.mObj=true;\n      const line=\"Stop. Anyone clearing those rocks is working right beside the drop.\";\n      const raised=cfRaise(\"Medic\",MTN_EV.ledge.note,line,(mode)=>{\n        if(mode===\"absorb\"){ RUN.mDec=\"DEFER\";\n          perfAward(\"Medic\",\"collab\",\"The objection changed the decision before anyone went near the edge\");\n          showFeedback({kind:'right',title:\"Objection taken up.\",\n            why:\"The decision is now Defer: take the way around. Submit it when you are ready.\"}); }\n        else { showFeedback({kind:'neutral',title:\"Override recorded.\",\n            why:\"The team goes ahead and clears the rocks. It is recorded in your name.\"}); mSubmit1(); }\n        render(); },\n        {stake:\"Whoever works beside the drop\",lose:\"If someone falls here, the Medic is treating them on a ledge.\"});\n      if(raised){ sbSay(\"Medic\",line,()=>render()); render(); return; }\n    }\n    S.fbNote=null; mSubmit1(); });\n  on(\"#mToMarker\",()=>{ sfxAct(\"tap\"); mGo(\"M3\"); mShow(ADV.scenes.mb,false); mMarkerZone(); });\n  document.querySelectorAll(\"[data-mprep]\").forEach(b=>b.onclick=()=>{\n    const k=b.dataset.mprep;\n    if(!RUN.bonusPrep&&(RUN.shelter||RUN.backup)){ toast(\"One preparation on this run.\"); return; }\n    if(k===\"shelter\"){ RUN.shelter=true; RUN.shelterUp=true; sfxAct(\"cloth\");\n      sbSay(\"Quartermaster\",\"The shelter is ready if we need to stop.\",()=>render()); }\n    else { RUN.backup={x:RUN.marker?RUN.marker.x-14:40,y:RUN.marker?RUN.marker.y+6:60}; sfxAct(\"place\");\n      sbSay(\"Navigator\",\"I've saved our last confirmed point.\",()=>render()); }\n    mShow(ADV.scenes.mb,false); render(); });\n  on(\"#mReady\",()=>{ sfxAct(\"tap\"); mWhiteout(); });\n  on(\"#mRecord2\",()=>{ if(!RUN.risk2||RUN.risk2.l==null)return; if(!runOnce(\"mRec2\"))return;\n    const w=$(\"#mWhy\"); RUN.riskWhy2=w?w.value:\"\"; RUN.risk2Recorded=true; SFX.submit();\n    perfAward(\"Medic\",\"crisis\",\"Re-read the hazard after the marker was lost\"); render(); });\n  document.querySelectorAll(\"[data-mdec2]\").forEach(b=>b.onclick=()=>{RUN.mDec2=b.dataset.mdec2;sfxAct(\"tap\");render();});\n  on(\"#mDec2Go\",()=>{ if(!RUN.mDec2||CF.pending)return;\n    /* moving on blind costs water: the Quartermaster can stop it, once */\n    if(RUN.mDec2===\"DEFER\"&&!RUN.m2Obj){ RUN.m2Obj=true;\n      const line=\"If we keep moving blind, we lose the trail, and every hour off it comes out of our water.\";\n      const raised=cfRaise(\"Quartermaster\",\"Visibility is near zero and the marker is gone\",line,(mode)=>{\n        if(mode===\"absorb\"){ RUN.mDec2=\"FIX\";\n          perfAward(\"Quartermaster\",\"collab\",\"The objection changed the decision before the team walked off blind\");\n          showFeedback({kind:'right',title:\"Objection taken up.\",\n            why:\"The decision is now Fix: shelter and wait. Submit it when you are ready.\"}); }\n        else { showFeedback({kind:'neutral',title:\"Override recorded.\",\n            why:\"The team keeps moving. It is recorded in your name.\"}); mSubmit2(); }\n        render(); },\n        {stake:\"Water and supplies\",lose:\"Every hour lost off the trail comes out of the Quartermaster's supplies.\"});\n      if(raised){ sbSay(\"Quartermaster\",line,()=>render()); render(); return; }\n    }\n    S.fbNote=null; mSubmit2(); });\n  on(\"#mToRound\",()=>{ sfxAct(\"tap\"); mRoundStart(); });\n  document.querySelectorAll(\"[data-hr]\").forEach(b=>b.onclick=()=>{\n    const hr=hrState(); if(hr.res[hr.i])return;\n    const k=HZ_ROUND[hr.i], h=HAZARDS[k], c=b.dataset.hr;\n    hr.res[hr.i]={k:k,choice:c,ok:c===h.g};\n    if(c===\"FIX\"){ spendTokens(h.cost,\"Fix \u2014 \"+h.name+\" (card cost \"+h.cost+\").\",b); sfxAct(\"snap\"); }\n    else sfxAct(\"tap\");\n    try{ (c===h.g?SFX.right:SFX.wrong)(); }catch(e){}\n    runLog(\"mountain\",\"Hazard \"+String(h.n).padStart(2,\"0\")+\" \u00b7 \"+c,\"Navigator\");\n    sbSay(\"Guide\",c===\"FIX\"?h.fix:h.def);\n    render(); });\n  on(\"#hrNext\",()=>{ const hr=hrState(); sfxAct(\"tap\"); hr.i++;\n    if(hr.i>=HZ_ROUND.length){ hr.i=HZ_ROUND.length-1; hr.done=true; vcStop(); }\n    else sbSay(\"Guide\",HAZARDS[HZ_ROUND[hr.i]].d);\n    render(); });\n}\nfunction mSubmit2(){\n  if(!RUN.mDec2||!runOnce(\"mDec2\"))return; SFX.submit(); CF.locked=true; cfPaint();\n  {\n    const fix=(RUN.mDec2===\"FIX\");\n    if(fix){ spendTokens(HAZARDS[7].cost,\"Fix \u2014 \"+HAZARDS[7].name+\" (card cost \"+HAZARDS[7].cost+\").\",$(\"#card\"));\n      rewardFx(null,\"loss\",\"\u2212\"+HAZARDS[7].cost+\" action tokens\");\n      RUN.shelterUp=true; sfxAct(\"cloth\"); mShow(ADV.scenes.mw,true);\n      sbSay(\"Quartermaster\",\"Shelter's up. We wait here until we can see the trail again.\",()=>render());\n    } else { sfxAct(\"wrong\"); mShow(ADV.scenes.mw,true);\n      sbSay(\"Navigator\",\"We're off the trail. We need our last confirmed point.\",()=>render()); }\n    runLog(\"mountain\",\"Hazard 08 \u00b7 \"+RUN.mDec2,\"Navigator\"); mGo(\"M5\");\n  }\n}\nfunction mBind2(){\n  const on=(s,f)=>document.querySelectorAll(s).forEach(e=>e.onclick=f);\n  on(\"#mRecover\",()=>{ if(!runOnce(\"mRecover\"))return; RUN.recovered=true; sfxAct(\"place\");\n    RUN.marker=RUN.backup; RUN.markerLost=false; mShow(ADV.scenes.mw,true);\n    rewardFx(null,\"gain\",\"Route recovered\");\n    perfAward(\"Navigator\",\"crisis\",\"Used the confirmed point to get the team back on the trail\");\n    sbSay(\"Navigator\",\"Back on the confirmed point. I can see where we are again.\",()=>render()); render(); });\n  on(\"#mSupport\",()=>{ if(!runOnce(\"mSupport\"))return; RUN.recovered=true; RUN.supportUsed=true;\n    RUN.bags=Math.max(0,RUN.bags-1); sfxAct(\"bag\");\n    rewardFx(null,\"loss\",\"Support called \u00b7 1 rescue bag\");\n    sbSay(\"Medic\",\"We are calling it in. Support is on the way to our last known position.\",()=>render()); render(); });\n  on(\"#mToDesert\",()=>{ sfxAct(\"tap\"); mountainToDesert(); });\n}\nfunction mSubmit1(){\n  if(!RUN.mDec||!runOnce(\"mDec1\"))return; SFX.submit(); CF.locked=true; cfPaint();\n  const fix=(RUN.mDec===\"FIX\");\n  if(fix){ spendTokens(HAZARDS[3].cost,\"Fix \u2014 \"+HAZARDS[3].name+\" (card cost \"+HAZARDS[3].cost+\").\",$(\"#card\"));\n    rewardFx(null,\"loss\",\"\u2212\"+HAZARDS[3].cost+\" action tokens\"); sfxAct(\"snap\");\n    RUN.injured=true; mShow(ADV.scenes.mb,false);\n    storyRockDust();\n    const rockFrame=$(\"#advImg\");\n    if(S.motion&&rockFrame.animate)rockFrame.animate([\n      {transform:\"scale(1.014)\"},{transform:\"translate(-2px,1px) scale(1.014)\"},\n      {transform:\"translate(2px,-1px) scale(1.014)\"},{transform:\"none\"}\n    ],{duration:245,easing:\"ease-out\"});\n    sbSay(\"Medic\",\"Stop. Someone's hurt. Give me room.\",()=>render());\n  } else { sfxAct(\"tap\"); sbSay(\"Navigator\",\"Back from the edge. I've marked the route around it.\",()=>render()); }\n  runLog(\"mountain\",\"Hazard 04 \u00b7 \"+RUN.mDec,\"Navigator\"); mGo(\"M2out\");\n}\n/* ---------- the rest of the pass: every remaining hazard card, Fix or Defer ---------- */\nconst HZ_ROUND=[0,1,2,4,5,6,8,9];\nfunction hrState(){ RUN.hr=RUN.hr||{i:0,res:[],done:false}; return RUN.hr; }\nfunction mRoundStart(){\n  hrState(); RUN.markerLost=true; RUN.scene=\"M6\"; rpHush(); S.fbNote=null;\n  mShow(ADV.scenes.mb,false);\n  sbSeq([[\"Guide\",\"More hazards on the way down. Fix or defer each one, and live with what it costs.\"],\n         [\"Guide\",HAZARDS[HZ_ROUND[0]].d]]);\n  render();\n}\nfunction hrGuideHTML(){\n  return `<details class=\"hrGuide\"><summary>The guide's rule for Fix or Defer</summary>${\n    GUIDE_ROWS.map(g=>`<div class=\"logLine\"><b>${esc(g[0])}</b><span>${esc(g[1])} \u2014 ${esc(g[2])}</span></div>`).join(\"\")}</details>`;\n}\nfunction hrPane(){\n  const hr=hrState(), n=HZ_ROUND.length;\n  const matched=hr.res.filter(r=>r&&r.ok).length;\n  if(hr.done){\n    const spent=hr.res.reduce((a,r)=>a+(r&&r.choice===\"FIX\"?HAZARDS[r.k].cost:0),0);\n    return now(\"Down the pass\",\"You decided \"+n+\" more hazards on the way down.\",\"Next: down to the desert.\")+\n      `<div class=\"infoBlk\"><b>${matched} of ${n} matched the guide</b><p>Action tokens spent in this round: ${spent}</p></div>`+\n      hr.res.map(r=>{const h=HAZARDS[r.k];\n        return `<div class=\"logLine\"><b>${r.ok?\"\u2713\":\"\u2717\"} ${esc(h.name)}</b><span>You: ${r.choice===\"FIX\"?\"Fix\":\"Defer\"} \u00b7 Guide: ${h.g===\"FIX\"?\"Fix\":\"Defer\"}</span></div>`;}).join(\"\")+\n      hrGuideHTML()+\n      `<button class=\"btn primary block\" id=\"mToDesert\" style=\"margin-top:12px\">Continue to the Desert</button>`;\n  }\n  const h=HAZARDS[HZ_ROUND[hr.i]], r=hr.res[hr.i];\n  const detail=h.n===2?\"ropeWorn\":h.n===5?\"frozen\":h.n===10&&r?.choice===\"FIX\"?\"aid\":null;\n  let b=now(\"Hazard \"+String(h.n).padStart(2,\"0\")+\" \u2014 \"+esc(h.name), esc(h.d),\n      r?\"Next: the next hazard.\":\"Next: fix it now, or defer it.\")+\n    `<p class=\"small dim\" style=\"margin-top:6px\">Card ${hr.i+1} of ${n} on the way down \u00b7 matched the guide so far: ${matched}</p>`+\n    (detail?`<div class=\"expHazardDetail\"><img src=\"${EXPEDITION_ART[detail]}\" alt=\"\"></div>`:\"\")+\n    hrGuideHTML();\n  if(!r){\n    b+=`<div class=\"choice\">\n        <button data-hr=\"FIX\">Fix<small>Costs ${h.cost} action token${h.cost>1?\"s\":\"\"}</small></button>\n        <button data-hr=\"DEFER\">Defer<small>Costs nothing now</small></button></div>`;\n  } else {\n    b+=`<div class=\"fbCard ${r.ok?\"right\":\"wrong\"}\"><b>${r.choice===\"FIX\"?\"Fix\":\"Defer\"} \u2014 ${r.ok?\"matches the guide.\":(\"the guide says \"+(h.g===\"FIX\"?\"Fix.\":\"Defer.\"))}</b>\n        <p>${esc(r.choice===\"FIX\"?h.fix:h.def)}</p>\n        ${r.choice===\"FIX\"?`<div class=\"cost\">Action cost: ${h.cost} token${h.cost>1?\"s\":\"\"}, from the card.</div>`:\"\"}</div>\n      <button class=\"btn primary block\" id=\"hrNext\">${hr.i+1<n?\"Next hazard\":\"See the round\"}</button>`;\n  }\n  return b;\n}\n/* the player sets the marker by touching the trail */\nfunction mMarkerZone(){\n  const host=$(\"#advLayers\"); if(!host)return;\n  host.querySelectorAll(\".dropZone\").forEach(e=>e.remove());\n  if(RUN.marker)return;\n  const z=document.createElement(\"button\");\n  z.className=\"dropZone live\"; z.style.left=\"54%\"; z.style.top=\"46%\"; z.style.width=\"12%\";\n  z.innerHTML=\"<span>Set the marker here</span>\";\n  z.setAttribute(\"aria-label\",\"Set the trail marker\");\n  z.onclick=()=>{ RUN.marker={x:54,y:46}; sfxAct(\"place\");\n    mShow(ADV.scenes.mb,false);\n    sbSay(\"Navigator\",\"This is the marker we'll use to stay on the trail.\",()=>render());\n    render(); };\n  host.appendChild(z);\n  const wld=$(\"#world\"); if(wld) wld.classList.add(\"placing\");\n}\nfunction mWhiteout(){\n  if(!runOnce(\"mWhite\"))return;\n  RUN.markerLost=true;\n  const wld=$(\"#world\"); if(wld) wld.classList.remove(\"placing\");\n  cfStage(\"Mountain \u00b7 whiteout\");\n  mShow(ADV.scenes.mw,true); sfxAct(\"rope\");\n  sbSeq([[\"Navigator\",\"Hold. I've lost the marker.\"],\n         [\"Medic\",\"We need to check the risk again before we move.\"]],()=>render());\n  mGo(\"M4\");\n}\nfunction mountainToDesert(){\n  RUN.stage=\"desert\"; RUN.scene=null;\n  const wld=$(\"#world\"); if(wld) wld.classList.remove(\"placing\");\n  sbScene(SB.mtnOut,[],\"travel\");\n  const note=RUN.recovered\n    ? \"You lost the trail, then used a confirmed point to find your way back. That's Dynamic Adaptation.\"\n    : \"When the marker disappeared, you checked the risk again. That's Dynamic Adaptation.\";\n  sbSeq([[\"Guide\",note],\n         [\"Guide\",\"The trail leads down to two desert routes. This time, each team has a different part of the picture.\"]],\n    ()=>{ if(RUN.stage===\"desert\"&&!RUN.scene) goZone(3,\"done\"); });\n}\n\n/* ================= Desert D1..D5 + Arrival (storyboard) ================= */\nconst DES_EV={\n  tower:{by:\"Navigator\", t:\"The tower\", note:\"Closer, but the wall is cracked\",\n         line:\"The tower is closer, but there are cracks in the wall.\", x:12, y:15, img:\"crack\"},\n  riverbed:{by:\"Navigator\", t:\"The riverbed\", note:\"Cover from the wind, but longer \u00b7 can flood if the storm shifts\",\n         line:\"The riverbed gives us cover from the wind. It's the longer route.\", x:26, y:15, img:\"riverbed\"},\n  team:{by:\"Medic\", t:\"Team condition\", note:\"Two members struggling \u00b7 needs a stop point\",\n         line:\"Two people are already struggling. Where can we stop if they need a break?\", x:40, y:15, img:\"stops\"},\n  worst:{by:\"Medic\", t:\"Worst case on each route\", note:\"Tower collapse: crush injuries \u00b7 riverbed flood: drowning risk for the weakest\",\n         line:\"If the tower comes down, we are treating crush injuries with no shelter.\", x:54, y:15, img:\"tower\"},\n  water:{by:\"Quartermaster\", t:\"Water left\", note:\"Two bottles \u00b7 no food\",\n         line:\"We have two bottles left. I need to know how long we'll be out there.\", x:68, y:15, img:\"stops\"},\n  exposure:{by:\"Quartermaster\", t:\"Cost of the longer route\", note:\"Longer outside doubles consumption\",\n         line:\"Longer outside doubles what we drink, and dust gets into open water.\", x:82, y:15, img:\"riverbed\"}\n};\nconst ROUTE_NAME={tower:\"the tower route\", riverbed:\"the riverbed route\"};\nfunction dNote(k){ let n=DES_EV[k].note; if(k===\"team\"&&RUN.injured) n+=\" \u00b7 plus one injured on the pass\"; return n; }\nfunction desExtra(k){\n  if(k===\"riverbed\") return [\"Navigator\",\"If the storm shifts, that riverbed can flood fast.\"];\n  if(k===\"worst\") return [\"Medic\",\"And if the riverbed floods, our two weakest are the ones at risk of drowning.\"];\n  if(k===\"team\"&&RUN.injured) return [\"Medic\",\"And the climber who was hurt on the pass is still with us.\"];\n  return null;\n}\nfunction dPane(){\n  const st=RUN.scene; let body=\"\";\n  const shared=Object.keys(RUN.dev||{});\n  if(st===\"D1\"){\n    body=now(\"Two routes, three partial pictures\",\n      \"Each team is holding something the others need. Ask for it \u2014 nothing moves onto the map on its own.\",\n      shared.length<6?`Next: ${6-shared.length} still unshared.`:\"Next: set the first route.\")+\n      `<div class=\"askRow\">${Object.keys(DES_EV).map(k=>`<button data-dev=\"${k}\" ${RUN.dev&&RUN.dev[k]?\"disabled\":\"\"}>\n        <b>${esc(DES_EV[k].t)}</b><small>${esc(DES_EV[k].by)}</small></button>`).join(\"\")}</div>`+\n      (shared.length?`<div class=\"hr\"></div>`+shared.map(k=>`<div class=\"logLine\"><b>${esc(DES_EV[k].by)}</b><span>${esc(dNote(k))}</span></div>`).join(\"\"):\"\")+\n      `<button class=\"btn primary block\" id=\"dToRoute\" style=\"margin-top:12px\">${\n        shared.length===6?\"Set the initial route\":\"Decide on what we have (\"+shared.length+\" of 6)\"}</button>`;\n  }\n  else if(st===\"D2\"){\n    const miss=Object.keys(DES_EV).filter(k=>!(RUN.dev||{})[k]);\n    body=now(\"Set the route and say what you expect\",\n      \"Touch the route on the map, then record what you expect and the one sign that would change the plan.\",\n      RUN.route?\"Next: record the prediction.\":\"Next: touch a route on the scene.\")+\n      (miss.length?`<div class=\"fbCard wrong\"><b>Deciding on ${6-miss.length} of 6.</b>\n        <p>Still unshared: ${miss.map(k=>esc(DES_EV[k].by+\" \u2014 \"+DES_EV[k].note)).join(\"; \")}.</p></div>`:\"\")+\n      (RUN.route?`<div class=\"infoBlk\"><b>Initial route</b><p>${esc(ROUTE_NAME[RUN.route])}</p></div>\n        <label class=\"eyebrow\" style=\"display:block;margin-top:10px\">What do you expect if you take this route?</label>\n        <textarea class=\"field\" id=\"dExpect\">${esc(RUN.expect||\"\")}</textarea>\n        <label class=\"eyebrow\" style=\"display:block;margin-top:8px\">What would make you change your plan?</label>\n        <textarea class=\"field\" id=\"dSign\">${esc(RUN.sign||\"\")}</textarea>\n        <button class=\"btn primary block\" id=\"dLockRoute\">Lock the plan</button>`\n       :`<p class=\"small dim\" style=\"margin-top:8px\">Tap the tower on the left or the riverbed on the right.</p>`);\n  }\n  else if(st===\"D3wait\"){\n    body=now(\"Plan locked\",\"The route and the prediction are on the record.\",\n      \"Next: the facilitator reveals the sandstorm.\")+\n      `<div class=\"infoBlk\"><b>${esc(ROUTE_NAME[RUN.route])}</b><p>${esc(RUN.expect)}</p>\n        <p class=\"small dim\">Sign to watch for: ${esc(RUN.sign)}</p></div>`;\n  }\n  else if(st===\"D3\"){\n    body=now(\"The storm tests the prediction\",\n      \"Visibility is dropping and the far marker is gone. Keep the plan or change it \u2014 and say what the new sign is.\",\n      \"Next: confirm the route the team will walk.\")+\n      `<div class=\"infoBlk\"><b>Your first plan</b><p>${esc(ROUTE_NAME[RUN.route])} \u2014 ${esc(RUN.expect)}</p></div>\n       <div class=\"routeBtns\">\n        <button data-dkeep=\"keep\" aria-pressed=\"${RUN.changed===false}\">Keep route<small>${esc(ROUTE_NAME[RUN.route])}</small></button>\n        <button data-dkeep=\"change\" aria-pressed=\"${RUN.changed===true}\">Change route<small>${esc(ROUTE_NAME[RUN.route===\"tower\"?\"riverbed\":\"tower\"])}</small></button>\n       </div>\n       <textarea class=\"field\" id=\"dWhy\" placeholder=\"Which sign supports this, and whose information backs it?\">${esc(RUN.changeWhy||\"\")}</textarea>\n       <button class=\"btn primary block\" id=\"dConfirmRoute\" ${(RUN.changed!=null)?\"\":\"disabled\"}>Confirm the route</button>`;\n  }\n  else if(st===\"D4\"){\n    const r=RUN.routeConfirmed;\n    body=now(\"Brief the team with SBAR\",\n      \"Four short lines, then the instruction goes out. The route in the message is the route on the board.\",\n      \"Next: send the instructions.\")+\n      `<div class=\"sbar\">\n        <label>Situation \u2014 what changed</label><textarea class=\"field\" id=\"dS\" placeholder=\"What changed? Say it in one line.\">${esc(RUN.sbarS||\"\")}</textarea>\n        <label>Background \u2014 route, team and supplies</label><textarea class=\"field\" id=\"dB\" placeholder=\"The route, the team's condition, what we carry.\">${esc(RUN.sbarB||\"\")}</textarea>\n        <label>Assessment \u2014 the risk now</label><textarea class=\"field\" id=\"dA\" placeholder=\"What is the biggest risk right now?\">${esc(RUN.sbarA||\"\")}</textarea>\n        <label>Recommendation \u2014 what we do, who leads</label><textarea class=\"field\" id=\"dR\" placeholder=\"What we do, who leads, where we stop.\">${esc(RUN.sbarR||\"\")}</textarea>\n       </div>\n       <button class=\"btn primary block\" id=\"dSend\">Send instructions</button>`;\n  }\n  else if(st===\"D5\"){\n    const r=RUN.routeConfirmed;\n    const st2=RUN.readback;\n    body=now(\"Read-back before anyone moves\",\n      st2===\"none\"?\"The instruction is out. Decide what reply is enough before anyone moves.\"\n        :(st2===\"correct\"?\"The executor repeated the route and the stop point. You confirmed it.\"\n          :\"What came back confirms receipt, not understanding.\"),\n      st2===\"correct\"?\"Next: the crate moves.\":(st2===\"none\"?\"Next: decide what you accept.\":\"Next: get a read-back that names the route.\"))+\n      (st2===\"none\"?`<div class=\"askRow\" style=\"grid-template-columns:1fr\">\n          <button data-drb=\"general\">Accept \u201cUnderstood, we're on it.\u201d</button>\n          <button data-drb=\"correct\">Ask them to say the plan back to you</button>\n          <button data-drb=\"wrong\">Accept \u201cGot it, ${esc(ROUTE_NAME[r===\"tower\"?\"riverbed\":\"tower\"])}.\u201d</button>\n        </div>`\n       :(st2===\"correct\"?`<button class=\"btn primary block\" id=\"dMove\">Confirm and move</button>`\n         :`<div class=\"fbCard wrong\"><b>Route and action still need confirmation.</b>\n            <p>The team has not moved. Ask again for the route and the stop point.</p></div>\n           <button class=\"btn primary block\" id=\"dAskAgain\">Ask for a proper read-back</button>`));\n  }\n  else if(st===\"E1\"){\n    body=now(\"The crate is delivered\",\n      RUN.supportUsed?\"The crate reached the handover point, with support called on the way.\"\n        :\"The crate reached the handover point.\",\n      \"Next: look back at the three decisions that shaped the trip.\")+\n      `<div class=\"infoBlk\"><b>${RUN.supportUsed?\"Expedition complete with support\":\"Expedition complete\"}</b>\n        <p>Crate: ${RUN.crate.wet?\"arrived with water damage recorded\":\"arrived dry\"} \u00b7 Rescue bags left: ${RUN.bags}</p>\n        ${RUN.injured?\"<p>One climber was hurt on the pass and was carried through by the Medic.</p>\":\"\"}\n        ${RUN.routeConfirmed===\"tower\"&&RUN.towerSafe?\"<p>The team sheltered on the ground floor, away from the cracked wall.</p>\":\"\"}</div>\n       <button class=\"btn primary block\" id=\"dReview\">Review expedition</button>`;\n  }\n  else if(st===\"E2\"){\n    body=now(\"Three decisions that shaped the trip\",\"One on each island, read from what actually happened in this run.\",\"\")+\n      reviewHTML()+\n      perfBoard(false)+\n      `<button class=\"btn primary block\" id=\"dHome\">Back to the map</button>`;\n  }\n  const p=document.createElement(\"section\"); p.className=\"pane\";\n  p.innerHTML=`<div class=\"paneHead\"><h3>Participant \u00b7 Team 1</h3><span class=\"badge\">${RUN.scene&&RUN.scene[0]===\"E\"?\"Arrival\":\"Desert Crossing\"}</span></div>\n    ${guideBar()}${scoreStrip()}${hud()}${body}${cfBlockCard()}${fbNoteHTML()}${skipBox()}`;\n  return p;\n}\n\n/* ---------------- the expedition review: one decision per island ---------------- */\nfunction rvRow(ok,title,text){\n  return `<div class=\"rvRow ${ok===true?\"ok\":(ok===false?\"no\":\"\")}\"><span class=\"rvIc\">${ok===true?\"\u2713\":(ok===false?\"\u2717\":\"\u2022\")}</span>\n    <div><b>${esc(title)}</b><p>${text}</p></div></div>`;\n}\nfunction reviewHTML(){\n  const ev=RUN.evidence||{}, inv=RUN.inv||{res:[]};\n  const over=st=>CF.over.filter(o=>(o.stage||\"\").indexOf(st)===0)\n    .map(o=>rvRow(false,\"Override\",esc(o.by+\" went past \"+o.team+\"'s objection: \"+o.evidence+(o.why?\" \u2014 \u201c\"+o.why+\"\u201d\":\"\")))).join(\"\");\n  const invOk=(inv.res||[]).filter(r=>r&&r.ok).length;\n  const invHid=(inv.res||[]).filter((r,i)=>r&&r.ok&&INVENTORY[INV_DECK[i]].x).length;\n  const hidTotal=INV_DECK.filter(k=>INVENTORY[k].x).length;\n  const jOut=RUN.outcome||null, v=jVar();\n  const plan=(RUN.planPreps||RUN.preps||[]).map(k=>JUNGLE_PREPS[k].label).join(\" + \")||\"No plan locked\";\n  const outTxt={clear:\"The rain found nothing open.\",rope:\"The guy-line let go.\",variant:v.fail,\n    both:\"The line let go, and \"+String(v.fail||\"\").toLowerCase()}[jOut]||\"The rain was not revealed in this run.\";\n  const jEv=[\"rope\",\"peg\",v.ev].filter(k=>ev[k]).length;\n  const skipped=z=>S.skipped&&S.skipped[z];\n  const hrS=RUN.hr||{res:[]};\n  const played={1:!!((inv.res||[]).length||jEv||RUN.outcome),\n                2:!!((RUN._once&&RUN._once.mDec1)||Object.keys(RUN.mev||{}).length||hrS.res.length)};\n  /* skipped before anything happened: one line. Skipped partway: what was decided, then a note. */\n  const skipLine=z=>skipped(z)?rvRow(null,played[z]?\"Skipped partway\":\"Skipped\",\n    played[z]?\"The rest of this island was skipped in the demo.\":\"This island was skipped in the demo.\"):\"\";\n  const part=z=>skipped(z)&&played[z];\n  let h=`<div class=\"rvSec\"><div class=\"eyebrow\">1 \u00b7 Dense Jungle \u2014 the camp plan</div>`+\n    ((skipped(1)&&!played[1])?skipLine(1)+`</div>`:(\n    ((inv.res||[]).length?rvRow(part(1)&&inv.res.length<INV_DECK.length?null:invOk===INV_DECK.length,\"Supplies check\",\n      invOk+\" of \"+INV_DECK.length+\" items found \u00b7 \"+invHid+\" of \"+hidTotal+\" that were not on the checklist.\"):\"\")+\n    ((!part(1)||jEv||RUN.outcome)?rvRow(jEv>=3,\"Checked before preparing\",jEv+\" of 3 pieces of evidence were on the board before the plan was locked.\"):\"\")+\n    ((!part(1)||RUN.outcome)?rvRow(jOut?jOut===\"clear\":null,\"Plan: \"+plan,esc(outTxt)+(RUN.fixed?\" The team put it right after the rain.\":\"\")):\"\")+\n    over(\"Jungle\")+skipLine(1)+`</div>`));\n  const g4=HAZARDS[3].g, g8=HAZARDS[7].g, FD=x=>x===\"FIX\"?\"Fix\":\"Defer\";\n  const rd=o=>(o&&o.l!=null)?(HM_L[o.l]+\" \u00d7 \"+HM_S[o.s]+\" \u2014 \"+HM_BAND(o.l,o.s)[0]):\"not recorded\";\n  const hr=RUN.hr||{res:[]}, hrOk=hr.res.filter(r=>r&&r.ok).length;\n  h+=`<div class=\"rvSec\"><div class=\"eyebrow\">2 \u00b7 Mountain Pass \u2014 fix or defer</div>`+\n    ((skipped(2)&&!played[2])?skipLine(2)+`</div>`:(\n    (RUN.mDec&&RUN._once&&RUN._once.mDec1\n      ?rvRow(RUN.mDec===g4,\"Blocked path: \"+FD(RUN.mDec),\"Assessed as \"+esc(rd(RUN.risk))+\". Guide: \"+FD(g4)+\". \"+\n        esc(RUN.mDec===\"FIX\"?HAZARDS[3].fix:HAZARDS[3].def))\n      :(part(2)?\"\":rvRow(null,\"Blocked path\",\"Not decided in this run.\")))+\n    (RUN.mDec2&&RUN._once&&RUN._once.mDec2\n      ?rvRow(RUN.mDec2===g8,\"Whiteout: \"+FD(RUN.mDec2),\"Re-assessed as \"+esc(rd(RUN.risk2))+\". Guide: \"+FD(g8)+\". \"+\n        esc(RUN.mDec2===\"FIX\"?HAZARDS[7].fix:HAZARDS[7].def))\n      :\"\")+\n    (hr.res.length?rvRow(hrOk===HZ_ROUND.length,\"Hazards on the way down\",hrOk+\" of \"+HZ_ROUND.length+\" matched the guide.\"):\"\")+\n    over(\"Mountain\")+skipLine(2)+`</div>`));\n  const nd=Object.keys(RUN.dev||{}).length, rc=RUN.routeConfirmed;\n  h+=`<div class=\"rvSec\"><div class=\"eyebrow\">3 \u00b7 Desert Crossing \u2014 the route</div>`+\n    rvRow(nd===6,\"Information shared\",nd+\" of 6 role facts were on the table before the route was set.\")+\n    (rc?rvRow(rc===\"tower\",\"Route: \"+ROUTE_NAME[rc],\n      (RUN.route&&RUN.route!==rc?\"Changed from \"+esc(ROUTE_NAME[RUN.route])+\" after the storm. \":\"\")+\n      (rc===\"tower\"?(RUN.towerSafe?\"Ground floor only, away from the cracked wall, as the Medic asked.\"\n                                  :\"The plan never said where to shelter inside a cracked tower.\")\n                   :\"The riverbed is slower and can flood with the two weakest members.\")):rvRow(null,\"Route\",\"Not confirmed in this run.\"))+\n    rvRow(!!RUN.sbarS,\"SBAR briefing\",RUN.sbarS?\"Sent before anyone moved.\":\"Not sent.\")+\n    rvRow(RUN.rbFirst===\"correct\",\"Read-back\",RUN.rbFirst===\"correct\"?\"The plan was said back before the team moved.\"\n      :(RUN.readback===\"correct\"?\"The first reply was accepted without checking it. The team asked again before moving.\":\"No read-back was confirmed.\"))+\n    over(\"Desert\")+\n    `<div class=\"infoBlk\"><b>Model answer</b><p>${esc(DESERT.model)}</p></div></div>`+\n    `<div class=\"infoBlk\" style=\"margin-top:12px\"><b>Score</b><p>Shield tokens: ${S.shields} \u00b7 Action tokens spent: ${S.spent}</p></div>`;\n  return h;\n}\n/* ---------------- Desert + Arrival wiring ---------------- */\nfunction dLayers(){\n  const L=[];\n  /* the shared facts sit as a tidy row of cards until the storm hits */\n  if([\"D1\",\"D2\",\"D3wait\"].indexOf(RUN.scene)>=0)\n    Object.keys(RUN.dev||{}).forEach(k=>{const e=DES_EV[k];\n      L.push({id:k, src:SB.ev[e.img], x:e.x, y:e.y, w:12, z:4, card:true});});\n  L.push({id:\"crate\",src:EXPEDITION_ART[RUN.crate.wet?\"crateWet\":\"crate\"],x:61,y:89,w:10,z:5});\n  return L;\n}\nfunction dShow(scene,storm){\n  sbScene(scene||SB.desertIn, dLayers(),\"desert\",storm?\"sandstorm\":\"\");\n  const ov=$(\"#advScene\"); let s=document.getElementById(\"sbSand\");\n  if(storm&&!s){ s=document.createElement(\"div\"); s.id=\"sbSand\"; ov.appendChild(s); }\n  if(!storm&&s) s.remove();\n}\nfunction dGo(sc){ RUN.scene=sc; rpHush(); render(); }\nfunction dStart(){\n  RUN.stage=\"desert\"; RUN.scene=\"D1\"; RUN.dev={}; RUN.readback=\"none\";\n  cfStage(\"Desert \u00b7 the route\"); S.fbNote=null; rpHush();\n  dShow(SB.desertIn,false);\n  sbSay(\"Guide\",\"You have two routes. Before you choose, find out what the other teams know.\");\n  render();\n}\nfunction dRouteZones(){\n  const host=$(\"#advLayers\"); if(!host)return;\n  host.querySelectorAll(\".dropZone\").forEach(e=>e.remove());\n  if(RUN.scene!==\"D2\"||RUN.route)return;\n  [[\"tower\",22,34],[\"riverbed\",80,52]].forEach(([k,x,y])=>{\n    const z=document.createElement(\"button\");\n    z.className=\"dropZone live\"; z.style.left=x+\"%\"; z.style.top=y+\"%\"; z.style.width=\"13%\";\n    z.innerHTML=`<span>${k===\"tower\"?\"Watchtower\":\"Dry riverbed\"}</span>`;\n    z.setAttribute(\"aria-label\",\"Choose \"+ROUTE_NAME[k]);\n    z.onclick=()=>{ RUN.route=k; sfxAct(\"place\");\n      perfAward(\"Navigator\",\"collab\",\"Set the first route with the evidence on the table\");\n      dShow(SB.desertIn,false); render(); };\n    host.appendChild(z);\n  });\n  const wld=$(\"#world\"); if(wld) wld.classList.add(\"placing\");\n}\nfunction dBind(){\n  const on=(s,f)=>document.querySelectorAll(s).forEach(e=>e.onclick=f);\n  document.querySelectorAll(\"[data-dev]\").forEach(b=>b.onclick=()=>{\n    const k=b.dataset.dev; RUN.dev=RUN.dev||{}; if(RUN.dev[k])return;\n    RUN.dev[k]=true; sfxAct(\"tap\");\n    evShare(k,DES_EV[k].by,dNote(k));\n    perfAward(DES_EV[k].by,\"evidence\",dNote(k));\n    dShow(SB.desertIn,false);\n    const ex=desExtra(k);\n    if(ex) sbSeq([[DES_EV[k].by,DES_EV[k].line],ex],()=>render());\n    else sbSay(DES_EV[k].by,DES_EV[k].line,()=>render());\n    render(); });\n  on(\"#dToRoute\",()=>{ sfxAct(\"tap\"); dGo(\"D2\"); dRouteZones(); });\n  const ex=$(\"#dExpect\"); if(ex) ex.oninput=()=>{RUN.expect=ex.value;};\n  const sg=$(\"#dSign\"); if(sg) sg.oninput=()=>{RUN.sign=sg.value;};\n  on(\"#dLockRoute\",()=>{\n    if(!RUN.expect||!RUN.expect.trim()||!RUN.sign||!RUN.sign.trim()){ toast(\"Record both answers first.\"); return; }\n    if(CF.pending) return;\n    /* the Medic holds the weakest members' stake and can stop either route, once */\n    if(!RUN.dObj){ RUN.dObj=true;\n      const tower=(RUN.route===\"tower\");\n      const ev=tower?\"If the tower comes down, the team is treating crush injuries with no shelter\"\n                    :\"A flash flood in the riverbed puts the two weakest members at drowning risk\";\n      const line=tower?\"If we go to the tower, nobody goes near that cracked wall.\"\n                      :\"If the storm shifts, the riverbed floods, and our two weakest cannot outrun water.\";\n      const raised=cfRaise(\"Medic\",ev,line,(mode)=>{\n        if(mode===\"absorb\"){\n          perfAward(\"Medic\",\"collab\",\"The objection shaped the route plan before the storm\");\n          if(tower){ RUN.towerSafe=true;\n            showFeedback({kind:'right',title:\"Objection taken up.\",\n              why:\"The plan now says: ground floor only, away from the cracked wall.\"});\n            dLockNow(); }\n          else { RUN.route=null; RUN.riverbedRejected=true;\n            showFeedback({kind:'right',title:\"Objection taken up.\",\n              why:\"Choose the route again with the flood risk on the table.\"}); }\n        } else {\n          showFeedback({kind:'neutral',title:\"Override recorded.\",\n            why:\"The plan goes ahead as it is. It is recorded in your name.\"});\n          dLockNow(); }\n        render(); });\n      if(raised){ sbSay(\"Medic\",line,()=>render()); render(); return; }\n    }\n    S.fbNote=null; dLockNow(); });\n  document.querySelectorAll(\"[data-dkeep]\").forEach(b=>b.onclick=()=>{\n    RUN.changed=(b.dataset.dkeep===\"change\"); sfxAct(\"tap\"); render(); });\n  const wy=$(\"#dWhy\"); if(wy) wy.oninput=()=>{RUN.changeWhy=wy.value;};\n  on(\"#dConfirmRoute\",()=>{ if(RUN.changed==null)return;\n    if(!(RUN.changeWhy||\"\").trim()){ toast(\"Write the sign that supports this, and whose information backs it.\"); return; }\n    if(!runOnce(\"dConfirm\"))return;\n    RUN.routeConfirmed=RUN.changed?(RUN.route===\"tower\"?\"riverbed\":\"tower\"):RUN.route;\n    SFX.submit();\n    perfAward(\"Navigator\",\"crisis\",(RUN.changed?\"Changed\":\"Held\")+\" the route after the storm with a stated reason\");\n    runLog(\"desert\",\"Confirmed \"+ROUTE_NAME[RUN.routeConfirmed]+(RUN.changed?\" (changed)\":\" (held)\"),\"Navigator\");\n    const line=RUN.routeConfirmed===\"tower\"\n      ? \"We're taking the tower route. I've marked the meeting point away from the cracked wall.\"\n      : \"We're taking the riverbed route. I've marked the point we can confirm.\";\n    if(RUN.changed) sbSeq([[\"Navigator\",line],\n      [\"Quartermaster\",\"The gear is packed for the first route. Give me a moment to set it up for this one.\"]],()=>render());\n    else sbSay(\"Navigator\",line,()=>render());\n    dGo(\"D4\"); });\n  [\"dS\",\"dB\",\"dA\",\"dR\"].forEach((id,i)=>{const e=$(\"#\"+id);\n    if(e) e.oninput=()=>{ RUN[[\"sbarS\",\"sbarB\",\"sbarA\",\"sbarR\"][i]]=e.value; };});\n  on(\"#dSend\",()=>{\n    const f=[$(\"#dS\"),$(\"#dB\"),$(\"#dA\"),$(\"#dR\")].map(e=>e?e.value.trim():\"\");\n    if(f.some(x=>!x)){ toast(\"Fill all four SBAR lines.\"); return; }\n    if(!runOnce(\"dSend\"))return;\n    RUN.sbarS=f[0];RUN.sbarB=f[1];RUN.sbarA=f[2];RUN.sbarR=f[3];\n    SFX.submit(); runLog(\"desert\",\"SBAR sent for \"+ROUTE_NAME[RUN.routeConfirmed],\"Navigator\");\n    dGo(\"D5\"); });\n  document.querySelectorAll(\"[data-drb]\").forEach(b=>b.onclick=()=>{\n    const v=b.dataset.drb; sfxAct(\"tap\"); if(!RUN.rbFirst) RUN.rbFirst=v;\n    if(v===\"correct\"){\n      RUN.readback=\"correct\";\n      perfAward(\"Medic\",\"collab\",\"Repeated the route and the stop point back before moving\");\n      rewardFx(null,\"gain\",\"Loop closed\");\n      sbSeq([[\"Navigator\",\"Tell me which route you'll take and where you'll stop.\"],\n             [\"Medic\",\"I'll take the confirmed route, stop at the agreed point, and check in.\"],\n             [\"Navigator\",\"Confirmed. You can move.\"]],()=>render());\n    } else {\n      RUN.readback=v; sfxAct(\"wrong\");\n      sbSay(\"Medic\",v===\"wrong\"?(\"Got it, \"+ROUTE_NAME[RUN.routeConfirmed===\"tower\"?\"riverbed\":\"tower\"]+\".\"):\"Understood, we're on it.\",()=>render());\n    }\n    render(); });\n  on(\"#dAskAgain\",()=>{ RUN.readback=\"none\"; sfxAct(\"tap\"); render(); });\n  on(\"#dMove\",()=>{ if(!runOnce(\"dMove\"))return;\n    sfxAct(\"crate\"); dArrive(); });\n  on(\"#dReview\",()=>{ sfxAct(\"tap\"); dGo(\"E2\"); });\n  on(\"#dHome\",()=>{ sfxAct(\"tap\"); RUN.scene=null; RUN.stage=\"done\";\n    sbScene(SB.arrival,[]); S.step=\"final\"; render(); });\n}\nfunction dLockNow(){\n  if(!RUN.route||!runOnce(\"dLock\"))return; CF.locked=true; cfPaint();\n  SFX.submit(); perfAward(\"Navigator\",\"collab\",\"Named the expectation and the sign before the storm\");\n  runLog(\"desert\",\"Initial route \"+ROUTE_NAME[RUN.route]+\" \u00b7 expected: \"+RUN.expect,\"Navigator\");\n  const wld=$(\"#world\"); if(wld) wld.classList.remove(\"placing\");\n  sbSay(\"Guide\",\"Your plan is on the record. Now watch what the storm does.\",()=>render());\n  dGo(\"D3wait\");\n}\nfunction dReveal(){\n  if(!runOnce(\"dStorm\"))return;\n  RUN.scene=\"D3\"; dShow(SB.desertStorm,true); sfxAct(\"cloth\");\n  sbSeq([[\"Navigator\",\"I can't see the riverbed entrance from here anymore.\"],\n         [\"Medic\",\"Hold here. I need to know where the team can stop.\"],\n         [\"Quartermaster\",\"Before we move, tell me which route I'm packing for.\"]],()=>render());\n  dGo(\"D3\");\n}\nfunction dArrive(){\n  RUN.stage=\"arrival\"; RUN.scene=\"E1\";\n  sbScene(SB.arrival,[{id:\"crate\",src:EXPEDITION_ART[RUN.crate.wet?\"crateWet\":\"crate\"],x:68,y:83,w:12,z:5}],\"arrival\");\n  rewardFx(null,\"gain\",\"Crate delivered\");\n  sbSeq([[\"Quartermaster\",\"Crate's down and secure. That's the delivery.\"],\n         [\"Guide\",\"You shared what each team knew. You checked your prediction when the storm changed the route. Then you repeated and confirmed the plan before moving. That's Closed-loop Communication.\"],\n         [\"Guide\",\"The crate made it. Let's look at three decisions that shaped the trip.\"]],()=>render());\n  render();\n}\nfunction dTrainer(){\n  const p=document.createElement(\"section\"); p.className=\"pane\";\n  const shared=Object.keys(RUN.dev||{});\n  p.innerHTML=`<div class=\"paneHead\"><h3>Facilitator</h3><span class=\"badge\">Desert Crossing</span></div>\n    ${hud()}\n    <div class=\"answerBox\"><div class=\"eyebrow\">Evidence on the table</div>\n      <p class=\"small\" style=\"margin:6px 0 0\">${shared.length} of 6 shared${shared.length<6?\" \u00b7 missing: \"+Object.keys(DES_EV).filter(k=>!RUN.dev[k]).map(k=>DES_EV[k].t+\" (\"+DES_EV[k].by+\")\").join(\", \"):\"\"}</p></div>\n    ${RUN.scene===\"D3wait\"?`<button class=\"btn primary block\" id=\"dRevealBtn\" style=\"margin-top:12px\">Reveal sandstorm</button>`:\"\"}\n    <div class=\"answerBox\" style=\"margin-top:10px\"><div class=\"eyebrow\">Round record</div>\n      <p class=\"small\" style=\"margin:6px 0 0\">Initial: ${RUN.route?esc(ROUTE_NAME[RUN.route]):\"not set\"} \u00b7\n        Confirmed: ${RUN.routeConfirmed?esc(ROUTE_NAME[RUN.routeConfirmed]):\"not set\"} \u00b7\n        Read-back: ${esc(RUN.readback)}</p></div>\n    ${RUN.sbarS?`<div class=\"answerBox\" style=\"margin-top:10px\"><div class=\"eyebrow\">Team SBAR</div>\n      <p class=\"small\" style=\"margin:6px 0 0\"><b>S</b> ${esc(RUN.sbarS)}</p>\n      <p class=\"small\" style=\"margin:3px 0 0\"><b>B</b> ${esc(RUN.sbarB||\"\")}</p>\n      <p class=\"small\" style=\"margin:3px 0 0\"><b>A</b> ${esc(RUN.sbarA||\"\")}</p>\n      <p class=\"small\" style=\"margin:3px 0 0\"><b>R</b> ${esc(RUN.sbarR||\"\")}</p>\n      ${RUN.awSbar?`<p class=\"small dim\" style=\"margin:6px 0 0\">SBAR ${RUN.awSbar===\"yes\"?\"accepted \u00b7 +1 shield\":\"not accepted\"}</p>`\n        :`<div style=\"display:flex;gap:8px;margin-top:8px\"><button class=\"btn\" id=\"dAwSbarY\" style=\"flex:1\">Accept SBAR \u00b7 +1</button>\n          <button class=\"btn\" id=\"dAwSbarN\" style=\"flex:1\">Not accepted</button></div>`}</div>`:\"\"}\n    ${RUN.routeConfirmed?`<div class=\"answerBox\" style=\"margin-top:10px\"><div class=\"eyebrow\">Model answer</div>\n      <p class=\"small\" style=\"margin:6px 0 0\">${esc(DESERT.model)}</p>\n      ${RUN.awDec?`<p class=\"small dim\" style=\"margin:6px 0 0\">Decision ${RUN.awDec===\"yes\"?\"accepted \u00b7 +1 shield\":\"not accepted\"}</p>`\n        :`<div style=\"display:flex;gap:8px;margin-top:8px\"><button class=\"btn\" id=\"dAwDecY\" style=\"flex:1\">Accept decision \u00b7 +1</button>\n          <button class=\"btn\" id=\"dAwDecN\" style=\"flex:1\">Not accepted</button></div>`}</div>`:\"\"}\n    ${perfBoard(false)}${ledger()}`;\n  return p;\n}\nfunction dTrainerBind(){ const b=$(\"#dRevealBtn\"); if(b) b.onclick=()=>{SFX.tap();dReveal();};\n  const on=(s,f)=>document.querySelectorAll(s).forEach(e=>e.onclick=f);\n  on(\"#dAwSbarY\",e=>{ if(RUN.awSbar)return; RUN.awSbar=\"yes\";\n    addShields(1,\"Desert crossing: SBAR accepted by the trainer.\",e.currentTarget); render(); });\n  on(\"#dAwSbarN\",()=>{ if(RUN.awSbar)return; RUN.awSbar=\"no\";\n    S.ledger.unshift({d:0,why:\"Desert crossing: SBAR not accepted.\"}); render(); });\n  on(\"#dAwDecY\",e=>{ if(RUN.awDec)return; RUN.awDec=\"yes\";\n    addShields(1,\"Desert crossing: decision accepted by the trainer.\",e.currentTarget); render(); });\n  on(\"#dAwDecN\",()=>{ if(RUN.awDec)return; RUN.awDec=\"no\";\n    S.ledger.unshift({d:0,why:\"Desert crossing: no shield for the decision.\"}); render(); });\n}\n\n/* ============ play guide + live score (shown to the participant) ============ */\nfunction guideBar(){\n  const g=guideFor();\n  return `<div class=\"gBar\">\n    <div class=\"gWhere\"><span class=\"gDot\"></span>${esc(g.where)}</div>\n    <div class=\"gTurn\">${esc(g.turn)}</div>\n    <div class=\"gDo\">${g.doIt}</div>\n    ${g.count?`<div class=\"gCount\">${g.count}</div>`:\"\"}\n    ${g.wait?`<div class=\"gWait\">${esc(g.wait)}</div>`:\"\"}\n    ${g.wait&&S.mode===\"participant\"?`<button class=\"btn block\" style=\"margin-top:8px\" onclick=\"document.querySelector('[data-mode=split]').click()\">Open the facilitator controls</button>`:\"\"}\n  </div>`;\n}\nfunction guideFor(){\n  const s=RUN.scene, st=RUN.stage;\n  const T=(w,t,d,c,wait)=>({where:w,turn:t,doIt:d,count:c,wait:wait});\n  if(st===\"jungle\"){\n    const n=RUN.preps.length;\n    const dots=(a,b)=>`<span class=\"gDots\">${Array.from({length:b},(_,i)=>`<i class=\"${i<a?\"on\":\"\"}\"></i>`).join(\"\")}</span><b>${a}/${b}</b>`;\n    if(s===\"J0\"){ const iv=RUN.inv||{res:[]};\n      return T(\"Dense Jungle \u00b7 supplies\",\"All three roles\",\n        iv.done?\"Supplies checked. Now inspect the camp.\":\"Read the clue and find the item, on the checklist or not.\",\n        dots(iv.res.filter(Boolean).length,INV_DECK.length)); }\n    if(s===\"J1\")  return T(\"Dense Jungle \u00b7 the camp\",\"Navigator \u2014 your call\",\"Look around the camp before anything is packed.\");\n    if(s===\"J2\")  return T(\"Dense Jungle \u00b7 gathering evidence\",\"All three roles\",\n      \"Touch what each role can see. Anything you share goes on the board.\", dots(evCount(),3));\n    if(s===\"J2peg\")return T(\"Dense Jungle \u00b7 the anchor point\",\"Navigator\",\"Say what changed down here, then record it.\");\n    if(s===\"J3\")  return T(\"Dense Jungle \u00b7 preparations\",\"Quartermaster \u2014 your call\",\n      n===0?\"Take one tool from the tray. Drag it to the camp, or tap the tool and then its place.\"\n      :(n<2?\"One more. Each tool has one right place in the scene.\"\n           :\"Name the risk you are leaving open, then lock the plan.\"), dots(n,2));\n    if(s===\"J4wait\")return T(\"Dense Jungle \u00b7 plan locked\",\"Facilitator\",\"Nothing to do \u2014 the plan is on the record.\",null,\n      \"Waiting for the facilitator to reveal the rain.\");\n    if(s===\"J4\")  return T(\"Dense Jungle \u00b7 after the rain\",\"Your team\",\n      jOutcome()===\"clear\"?\"Nothing to repair. Carry the crate up the pass.\"\n        :(jRepairsLeft().length?\"Put right what the rain exposed.\":\"The repair is done. Carry the crate up the pass.\"));\n  }\n  if(st===\"mountain\"){\n    const n=Object.keys(RUN.mev||{}).length;\n    const dots=(a,b)=>`<span class=\"gDots\">${Array.from({length:b},(_,i)=>`<i class=\"${i<a?\"on\":\"\"}\"></i>`).join(\"\")}</span><b>${a}/${b}</b>`;\n    if(s===\"M1\") return T(\"Mountain Pass \u00b7 the blocked trail\",\"All three roles\",\n      \"Touch the rubble, the ledge and the way around. Two pieces open the assessment.\", dots(n,3));\n    if(s===\"M2\") return T(\"Mountain Pass \u00b7 risk assessment\",\"Medic \u2014 your call\",\n      RUN.riskRecorded?\"Now choose: clear the rocks, or take the way around.\":\"Pick a likelihood and a severity, then record it.\");\n    if(s===\"M2out\")return T(\"Mountain Pass \u00b7 result\",\"Your team\",\"Read what happened, then set your marker.\");\n    if(s===\"M3\") return T(\"Mountain Pass \u00b7 your marker\",\"Navigator \u2014 your call\",\n      RUN.marker?\"Choose what you can prepare before moving out.\":\"Tap the glowing point on the trail to set your marker.\");\n    if(s===\"M4\") return T(\"Mountain Pass \u00b7 whiteout\",\"Medic \u2014 your call\",\n      RUN.risk2Recorded?\"Decide again: shelter and wait, or keep moving.\":\"Read the hazard again and say what changed.\");\n    if(s===\"M5\") return T(\"Mountain Pass \u00b7 result\",\"Your team\",\n      (RUN.recovered||RUN.mDec2===\"FIX\")?\"Continue down the pass.\":\"Deal with where the team ended up.\");\n    if(s===\"M6\"){ const hr=RUN.hr||{res:[]};\n      return T(\"Mountain Pass \u00b7 down the pass\",\"Your team\",\n        hr.done?\"Head down to the desert.\":\"Fix or defer each hazard. The guide's rule is there if you need it.\",\n        dots(hr.res.filter(Boolean).length,HZ_ROUND.length)); }\n  }\n  if(st===\"desert\"||st===\"arrival\"){\n    const n=Object.keys(RUN.dev||{}).length;\n    const dots=(a,b)=>`<span class=\"gDots\">${Array.from({length:b},(_,i)=>`<i class=\"${i<a?\"on\":\"\"}\"></i>`).join(\"\")}</span><b>${a}/${b}</b>`;\n    if(s===\"D1\") return T(\"Desert Crossing \u00b7 the fork\",\"All three roles\",\n      \"Ask each role for what only they can see.\", dots(n,6));\n    if(s===\"D2\") return T(\"Desert Crossing \u00b7 first route\",\"Navigator \u2014 your call\",\n      RUN.route?\"Say what you expect and name the sign that would change it.\":\"Tap the tower on the left or the riverbed on the right.\");\n    if(s===\"D3wait\")return T(\"Desert Crossing \u00b7 plan locked\",\"Facilitator\",\"Nothing to do yet.\",null,\n      \"Waiting for the facilitator to reveal the sandstorm.\");\n    if(s===\"D3\") return T(\"Desert Crossing \u00b7 the storm\",\"Your team\",\"Keep the route or change it, and say what the new sign is.\");\n    if(s===\"D4\") return T(\"Desert Crossing \u00b7 briefing\",\"Navigator\",\"Fill the four lines, then send the instruction.\");\n    if(s===\"D5\") return T(\"Desert Crossing \u00b7 read-back\",\"Navigator \u2014 your call\",\n      RUN.readback===\"correct\"?\"The loop is closed. Move the crate.\":\"Choose what you accept as a read-back before anyone moves.\");\n    if(s===\"E1\") return T(\"Arrival\",\"Your team\",\"The crate is down. Look at what shaped the trip.\");\n    if(s===\"E2\") return T(\"Arrival \u00b7 review\",\"Your team\",\"Three decisions from this run.\");\n  }\n  return T(\"The Expedition Challenge\",\"\",\"Follow the step on screen.\");\n}\n/* the live standings the participant can see */\nfunction scoreStrip(){\n  const teams=[\"Navigator\",\"Medic\",\"Quartermaster\"];\n  const best=Math.max(...teams.map(perfTotal));\n  return `<div class=\"scoreStrip\">\n    ${teams.map(t=>{\n      const n=perfTotal(t), lead=(n===best&&best>0);\n      return `<div class=\"ssTeam${lead?\" lead\":\"\"}\">\n        <b>${t}</b><span class=\"ssPts\">${n}<small>/9</small></span>\n        ${t===\"Navigator\"?`<span class=\"ssYou\">you</span>`:`<span class=\"ssSim\">simulated</span>`}</div>`;}).join(\"\")}\n    <div class=\"ssShared\"><span>${S.shields}</span> shields \u00b7 <span>${S.spent}</span> tokens spent</div>\n  </div>`;\n}\n\n/* the block card answers the same way in every scene, old engine or new */\nfunction cfBindButtons(legacy){\n  const resolve=(mode)=>{\n    const pending=CF.pending;\n    if(!pending)return;\n    const why=$(\"#aCfWhy\");\n    if(mode===\"override\"&&!legacy&&why&&!why.value.trim()){\n      toast(\"Name the reason before going ahead.\");\n      return;\n    }\n    CF.pending=null;\n    if(mode===\"absorb\"){\n      SFX.right();\n      cfUse(pending.by,pending.evidence,true);\n      const act=\"Took up \"+pending.by+\"'s objection\";\n      cfAct(\"Navigator\",legacy?act+\" and changed how the decision was carried out\":act,\"absorb\");\n    } else {\n      SFX.flip();\n      cfOver(\"Navigator\",pending.by,pending.evidence,why?why.value:\"\");\n    }\n    const done=cfResolve;\n    cfResolve=null;\n    cfPaint();\n    if(!legacy)rpHush();\n    done&&done(mode,pending);\n    if(!legacy)render();\n  };\n  document.querySelectorAll(\"#aCfAbsorb\").forEach(el=>el.onclick=()=>resolve(\"absorb\"));\n  document.querySelectorAll(\"#aCfOver\").forEach(el=>el.onclick=()=>resolve(\"override\"));\n}\n/* ---------------- Jungle wiring ---------------- */\nfunction jLockNow(){\n    if(RUN.preps.length!==2){ toast(\"Choose exactly two preparations.\"); return; }\n    if(!(RUN.openRisk||\"\").trim()){ toast(\"Name the risk you are leaving open.\"); return; }\n    if(!runOnce(\"jLock\"))return;\n    CF.locked=true; cfPaint();\n    SFX.submit(); runLog(\"jungle\",\"Locked: \"+RUN.preps.map(k=>JUNGLE_PREPS[k].label).join(\" + \")+\" \u00b7 left open: \"+RUN.openRisk,\"Quartermaster\");\n    jShowCamp(false);\n    /* the installs happen one after the other, each with its own sound */\n    const seq=RUN.preps.slice();\n    const playInstall=(i)=>{\n      if(i>=seq.length){ jGo(\"J4wait\"); return; }\n      const k=seq[i];\n      sfxAct(k===\"peg\"?\"mallet\":\"cloth\");\n      jShowCamp(false);\n      sbSay(\"Quartermaster\",JUNGLE_PREPS[k].done,()=>playInstall(i+1));\n    };\n    playInstall(0);\n    jGo(\"J4wait\");\n}\n\nfunction jGo(scene){ RUN.scene=scene; rpHush(); render(); }\nfunction jBind(){\n  const on=(s,f)=>document.querySelectorAll(s).forEach(e=>e.onclick=f);\n  const v=jVar();\n  document.querySelectorAll(\"[data-inv]\").forEach(b=>b.onclick=()=>invAnswer(b.dataset.inv,b));\n  on(\"#invOff\",()=>{ invState().off=true; SFX.tap(); render(); const t=$(\"#invTyped\"); if(t)t.focus(); });\n  const ivT=$(\"#invTyped\");\n  if(ivT){ ivT.oninput=()=>{ invState().typed=ivT.value; };\n    ivT.onkeydown=e=>{ if(e.key===\"Enter\"){ e.preventDefault(); const bb=$(\"#invCheck\"); if(bb)bb.click(); } }; }\n  on(\"#invCheck\",e=>{ const t=$(\"#invTyped\"), val=t?t.value:\"\";\n    if(!val.trim()){ toast(\"Name the item first.\"); return; } invAnswer(val,e.currentTarget); });\n  on(\"#invHint\",e=>{ const iv=invState(); if(iv.hint)return; iv.hint=true;\n    spendTokens(1,\"Tool: reveal first letter (\"+INVENTORY[INV_DECK[iv.i]].a+\").\",e.currentTarget); render(); });\n  on(\"#invNext\",()=>{ const iv=invState(); SFX.tap(); iv.i++; iv.hint=false; iv.off=false; iv.typed=\"\";\n    if(iv.i>=INV_DECK.length){ iv.i=INV_DECK.length-1; iv.done=true; vcStop(); }\n    else sbSay(\"Guide\",INVENTORY[INV_DECK[iv.i]].c);\n    render(); });\n  on(\"#invToCamp\",()=>{ SFX.tap(); jGo(\"J1\"); jShowCamp(false);\n    sbSay(\"Guide\",\"The camp is marked ready. Rain is coming. You have time for two preparations.\"); });\n  on(\"#jInspectCamp\",()=>{ SFX.tap();\n    sbSeq([[\"Quartermaster\",\"The tent is on the checklist. Are we ready to start loading?\"],\n           [\"Navigator\",\"Wait. That line is moving more than the others.\"],\n           [\"Medic\",\"Before we load, I want to check what the rain could reach.\"]]);\n    if(!RUN.variant) RUN.variant=\"ground\";   /* the seeded risk is fixed once the camp opens */\n    jGo(\"J2\"); });\n  document.querySelectorAll(\"[data-jchk]\").forEach(b=>b.onclick=()=>{\n    const k=b.dataset.jchk; SFX.pick();\n    if(k===\"rope\"){\n      sfxAct(\"rope\");\n      evShare(\"rope\",\"Navigator\",\"The guy-line on the left is slack while the others are tight\");\n      jShowCamp(false); layersFocus&&layersFocus(\"rope\");\n      sbSay(\"Navigator\",\"This line is loose. Let's see where it's tied down.\",()=>render());\n      render();\n    } else if(k===\"peg\"){\n      jGo(\"J2peg\"); rpShow(false);\n      sbScene(ADV.scenes.jp,[]);\n      sbSay(\"Guide\",\"Look at the anchor point. Nothing else moves while you are down here.\");\n    } else {\n      sfxAct(RUN.variant===\"roof\"?\"cloth\":\"water\");\n      evShare(v.ev,\"Medic\",v.evText);\n      jShowCamp(false);\n      sbSay(\"Medic\",v.medLine,()=>render());\n      render();\n    }});\n  on(\"#jGear\",()=>{ SFX.tap();\n    sbSay(\"Quartermaster\",\"I can set up two of these before the rain. Which risk are we leaving open?\",()=>render()); });\n  on(\"#jPegRec\",()=>{ const t=$(\"#jPegNote\"); if(t&&t.value.trim()) RUN.pegNote=t.value;\n    if(!(RUN.pegNote||\"\").trim()){ toast(\"Write what changed first.\"); return; }\n    evShare(\"peg\",\"Navigator\",\"The peg is leaning and the soil around it has moved\");\n    SFX.submit(); perfAward(\"Navigator\",\"evidence\",\"Read the anchor point up close and recorded it\");\n    rpShow(true); jGo(\"J2\"); jShowCamp(false); });\n  on(\"#jPegBack\",()=>{ rpShow(true); jGo(\"J2\"); jShowCamp(false); });\n  on(\"#jToPreps\",()=>{ sfxAct(\"tap\");\n    /* what was known before the rain is recorded here; the reward itself is\n       settled after the reveal, because it depends on the plan too */\n    RUN.knewBeforeRain=!!(RUN.evidence.peg&&RUN.evidence[v.ev]);\n    jGo(\"J3\"); });\n  document.querySelectorAll(\"[data-jprep]\").forEach(b=>b.onclick=()=>{\n    const k=b.dataset.jprep, i=RUN.preps.indexOf(k);\n    if(i>=0) RUN.preps.splice(i,1); else if(RUN.preps.length<2) RUN.preps.push(k);\n    SFX.pick(); jShowCamp(false); render(); });\n  /* keep typed text in session state so a re-render never wipes it */\n  const rk=$(\"#jOpenRisk\");\n  if(rk) rk.oninput=()=>{ RUN.openRisk=rk.value; };\n  const pn=$(\"#jPegNote\");\n  if(pn) pn.oninput=()=>{ RUN.pegNote=pn.value; };\n  on(\"#jLock\",()=>{\n    const r=$(\"#jOpenRisk\"); if(r&&r.value.trim()) RUN.openRisk=r.value;\n    if(CF.pending) return;                       /* a block holds the lock */\n    if(RUN.preps.length!==2){ toast(\"Choose exactly two preparations.\"); return; }\n    if(!(RUN.openRisk||\"\").trim()){ toast(\"Name the risk you are leaving open.\"); return; }\n    /* the role whose risk is really being left open gets to stop the plan, once.\n       A plan that covers both real risks is not objected to. */\n    const openRope=!jRopeSafe(), openVar=!jVarSafe();\n    if(!RUN.objRaised&&(openRope||openVar)){\n      RUN.objRaised=true;\n      const who=openRope?\"Quartermaster\":\"Medic\";\n      const ev=openRope\n        ? \"Nothing is holding that guy-line, and the wind has not dropped\"\n        : (RUN.variant===\"roof\"\n            ? \"Nothing covers the seam, and the packing area sits right under it\"\n            : \"Nothing is under the crate, and the water runs straight to it\");\n      const line=openRope\n        ? \"Hold on. If that line goes in the night, we are rebuilding the tent in the rain.\"\n        : (RUN.evidence[jVar().ev]\n            ? \"Wait. You are leaving the one thing I said the rain would reach.\"\n            : \"Wait. Nobody has checked where the rain will land, and that is the part we are leaving open.\");\n      const raised=cfRaise(who,ev,line,(mode)=>{\n        if(mode===\"absorb\"){\n          perfAward(who,\"collab\",\"Objection was taken into the plan before it was locked\");\n          showFeedback({kind:'right',title:\"Objection taken up.\",\n            why:\"Change a tool, or lock it knowing what you are carrying.\"});\n        } else if(mode===\"override\"){\n          RUN.overrodeBy=who;\n          showFeedback({kind:'neutral',title:\"Override recorded.\",\n            why:\"Nothing is deducted now. It is in your name, and the rain will show what it cost.\"});\n          jLockNow();\n        }\n        render();\n      }, JSTAKE[who]);\n      if(raised){ sbSay(who,line,()=>render()); render(); return; }\n    }\n    jLockNow(); });\n\n  on(\"#jFixRope\",()=>{ if(!runOnce(\"jFixRope\"))return; sfxAct(\"mallet\");\n    RUN.fixedRope=true; RUN.fixed=RUN.fixed?\"both\":\"rope\"; RUN.repaired=true;   /* the plan stays as it was locked */\n    SFX.submit();\n    jShowCamp(true);\n    sbSay(\"Quartermaster\",\"The line's gone! I've got this side. We need to secure it.\",()=>render());\n    perfAward(\"Quartermaster\",\"crisis\",\"Secured the anchor the moment the line let go\");\n    render(); });\n  on(\"#jFixVar\",()=>{ if(!runOnce(\"jFixVar\"))return;\n    sfxAct(RUN.variant===\"ground\"?\"crate\":\"cloth\");\n    RUN.fixedVar=true; RUN.fixed=RUN.fixed?\"both\":\"variant\"; RUN.repaired=true;\n    if(RUN.variant===\"ground\"){ RUN.crate.moved=true; }\n    else { RUN.seamCovered=true; }        /* the leak layer stops being drawn */\n    SFX.submit(); jShowCamp(true);\n    sbSay(v.failLine[0]===\"M\"?\"Medic\":\"Navigator\",v.failLine[1],()=>render());\n    perfAward(\"Medic\",\"crisis\",\"Acted on what the rain exposed instead of carrying it up the pass\");\n    render(); });\n  on(\"#jToMountain\",()=>{ SFX.tap(); jungleToMountain(); });\n}\nfunction jRevealRain(){\n  if(!runOnce(\"jRain\"))return;\n  RUN.rainRevealed=true;\n  /* lock what the plan was, so a later correction cannot rewrite the outcome */\n  RUN.planPreps=RUN.preps.slice();\n  RUN.outcome=jOutcome();\n  /* the spare preparation needs both: the evidence shared early AND a plan\n     that actually covered both risks */\n  if(RUN.knewBeforeRain&&RUN.outcome===\"clear\"&&runOnce(\"bonusPrep\")){\n    RUN.bonusPrep=true;\n    perfAward(\"Medic\",\"collab\",\"Shared the exposure evidence early and the plan covered both risks\");\n    rewardFx(null,\"gain\",\"Extra mountain preparation\");\n  }\n  const out=jOutcome(); const v=jVar();\n  if(out===\"variant\"||out===\"both\"){ if(RUN.variant===\"ground\") RUN.crate.wet=true; }\n  jShowCamp(true);\n  const line=(out===\"clear\")?[\"Quartermaster\",\"The line's holding, and our gear is protected. We can load.\"]\n           :(out===\"rope\")?[\"Quartermaster\",\"The line's gone! I've got this side. We need to secure it.\"]\n           :[v.failLine[0]===\"M\"?\"Medic\":\"Navigator\",v.failLine[1]];\n  runLog(\"jungle\",\"Rain revealed \u00b7 outcome: \"+out,\"Guide\");\n  sbSay(line[0],line[1],()=>{ if(RUN.stage===\"jungle\"&&RUN.scene===\"J4\") render(); });\n  jGo(\"J4\");\n}\nlet finishPassNarration=null;\nfunction clearPassHandoff(){\n  finishPassNarration=null;\n  $(\"#passHandoff\").hidden=true;\n}\ndocument.getElementById(\"passSkipNarration\").onclick=()=>{\n  if(!finishPassNarration)return;\n  SFX.tap();\n  finishPassNarration();\n};\nfunction jungleToMountain(){\n  if(finishPassNarration)return;\n  RUN.stage=\"mountain\"; RUN.scene=null;\n  sbScene(SB.jungleOut,[],\"travel\");\n  const note=RUN.evidence.rope&&RUN.evidence.peg\n    ? \"You spotted the loose line and checked where it was tied. That's Detection and Micro-observation.\"\n    : (RUN.rainRevealed&&RUN.fixed\n      ? \"The rain showed you what the checklist had missed. You found the weak point and acted on it.\"\n      : \"The checklist said ready, but the loose line was still there. That's Complacency Risk.\");\n  const continueToPass=()=>{\n    if(finishPassNarration!==continueToPass)return;\n    clearPassHandoff();\n    if(RUN.stage!==\"mountain\"||RUN.scene)return;\n    vcDone=null;\n    vcStop();\n    goZone(2,\"done\");\n    $(\"#trGo\").focus({preventScroll:true});\n  };\n  finishPassNarration=continueToPass;\n  $(\"#passHandoff\").hidden=false;\n  document.querySelectorAll(\"#jToMountain\").forEach(button=>{button.disabled=true;});\n  $(\"#passSkipNarration\").focus({preventScroll:true});\n  sbSeq([[\"Guide\",note],\n         [\"Guide\",\"The crate is ready to move. Follow the trail uphill. The next decision is about the path itself.\"]],\n    continueToPass);\n}\n/* ================= Jungle J1..J5 (storyboard) ================= */\nconst JUNGLE_VARIANT={\n  ground:{ev:\"groundpool\", evText:\"Water collects in the dip and runs to the crate\",\n          medLine:\"If water collects here, it can reach the bottom of the crate.\",\n          checkBtn:\"Check the ground\", risk:\"water reaching the crate\",\n          fail:\"Water reached the base of the crate.\",\n          failLine:[\"M\",\"Water's under the crate. Move it to the dry patch.\"],\n          fixBtn:\"Move the crate\", fixedBy:\"ground\"},\n  roof:{ev:\"roofgap\", evText:\"A gap in the roof seam sits over the packing area\",\n        medLine:\"If rain comes through that gap, it will land right where we're packing.\",\n        checkBtn:\"Check the roof seam\", risk:\"rain through the roof seam\",\n        fail:\"Rain came through the seam into the packing area.\",\n        failLine:[\"N\",\"Rain's coming through the seam. The packing area's getting wet.\"],\n        fixBtn:\"Cover the packing area\", fixedBy:\"roof\"}\n};\nconst JSTAKE={\n  Quartermaster:{stake:\"The tent and the gear\",\n    lose:\"If the line goes in the night, the Quartermaster is the one rebuilding the camp in the rain.\"},\n  Medic:{stake:\"The crate and the people packing it\",\n    lose:\"If the rain reaches the packing area, the Medic is treating the cold and the wet.\"}};\nconst JUNGLE_PREPS={\n  peg:{label:\"Anchor peg\", covers:\"rope\", by:\"Quartermaster\",\n       done:\"The line is anchored and holding.\", layer:null},\n  rainfly:{label:\"Fit rainfly\", covers:\"roof\", by:\"Quartermaster\",\n       done:\"The rainfly is over the tent.\", layer:\"rainfly\"},\n  groundsheet:{label:\"Lay groundsheet\", covers:\"ground\", by:\"Quartermaster\",\n       done:\"The groundsheet is under the packing area.\", layer:\"ground\"}\n};\nfunction jVar(){return JUNGLE_VARIANT[RUN.variant||\"ground\"];}\n/* the camp frame: background + whatever the session has changed in it */\nfunction jCampLayers(){\n  const L=[];\n  const out=(RUN.stage===\"jungle\"&&RUN.rainRevealed)?jOutcome():null;\n  /* the tent itself: upright, or collapsed on the side the rope let go */\n  const tentDown=((out===\"rope\"||out===\"both\")&&!RUN.fixedRope);\n  L.push({id:\"tent\", src:tentDown?SB.tent.down:SB.tent.ok, x:30, y:58, w:34});\n  /* the guy-line the team may have anchored */\n  const ropeHeld=((RUN.planPreps||RUN.preps).indexOf(\"peg\")>=0)||RUN.fixedRope;\n  L.push({id:\"rope\", src:ropeHeld?\"data:image/webp;base64,\":\"data:image/webp;base64,\", x:21, y:72, w:20});\n  const plan=(RUN.planPreps||RUN.preps);\n  if(plan.indexOf(\"rainfly\")>=0||RUN.seamCovered) L.push({id:\"rainfly\", src:\"data:image/webp;base64,\", x:30, y:47, w:30});\n  if(plan.indexOf(\"groundsheet\")>=0) L.push({id:\"ground\", src:\"data:image/webp;base64,\", x:58, y:76, w:24});\n  /* the crate, dry or wet, at the packing spot or moved to dry ground */\n  L.push({id:\"crate\", src:SB.bag.crate, x:RUN.crate.moved?78:62, y:RUN.crate.moved?66:74, w:13});\n  if(RUN.crate.wet) L.push({id:\"wet\", src:SB.ev.cratewet, x:RUN.crate.moved?78:62, y:RUN.crate.moved?70:78, w:14, z:5});\n  /* the evidence the facilitator seeded for this run, once it has been shared */\n  const v=jVar();\n  if(RUN.evidence[v.ev]&&!jVarSafe()) L.push({id:v.ev, src:SB.ev[v.ev], card:true,\n    x:(RUN.variant===\"roof\")?36:58, y:(RUN.variant===\"roof\")?44:84, w:(RUN.variant===\"roof\")?22:20, z:4});\n  const leakShowing=(out===\"variant\"||out===\"both\")&&!(RUN.seamCovered||RUN.crate.moved);\n  if(leakShowing) L.push({id:\"fail\", src:SB.ev[v.ev===\"roofgap\"?\"seamleak\":\"cratewet\"],\n    x:(RUN.variant===\"roof\")?44:66, y:(RUN.variant===\"roof\")?58:80, w:22, z:6});\n  return L;\n}\nfunction jShowCamp(rain){\n  sbScene(rain?SB.campRain:SB.camp, jCampLayers(),\"jungle\",rain?\"rain\":\"\");\n  const ov=$(\"#advScene\");\n  if(ov){ let r=document.getElementById(\"sbRain\");\n    if(rain&&!r){ r=document.createElement(\"div\"); r.id=\"sbRain\"; ov.appendChild(r); }\n    if(!rain&&r) r.remove(); }\n}\n\n/* which risks the chosen preparations actually covered */\nfunction jCovered(){return (RUN.planPreps||RUN.preps).map(p=>JUNGLE_PREPS[p].covers);}\nfunction jRopeSafe(){return jCovered().indexOf(\"rope\")>=0;}\nfunction jVarSafe(){return jCovered().indexOf(jVar().fixedBy)>=0;}\n/* the rain reads the plan: whatever was left open is what goes wrong */\n/* what the rain broke and the team has not yet put right: the anchor first, then the seeded risk */\nfunction jRepairsLeft(){\n  const out=jOutcome(), left=[];\n  if((out===\"rope\"||out===\"both\")&&!RUN.fixedRope) left.push(\"rope\");\n  if((out===\"variant\"||out===\"both\")&&!RUN.fixedVar) left.push(\"variant\");\n  return left;\n}\nfunction jOutcome(){\n  if(RUN.outcome) return RUN.outcome;      /* settled at reveal, never re-read */\n  const rope=jRopeSafe(), other=jVarSafe();\n  if(rope&&other) return \"clear\";\n  if(!rope&&other) return \"rope\";\n  if(rope&&!other) return \"variant\";\n  return \"both\";\n}\n/* ================= storyboard run: one session state =================\n   Everything a scene needs is read from here, so a view switch, a rotate or a\n   double press replays the same frame instead of rebuilding a new one. */\nconst RUN={\n  stage:\"home\",          /* home | jungle | mountain | desert | arrival */\n  scene:null,            /* which frame is on screen */\n  variant:null,          /* facilitator picks: \"ground\" or \"roof\" */\n  evidence:{},           /* id -> {by, text, shared:true} */\n  preps:[],              /* jungle: chosen preparations, max 2 */\n  openRisk:null,         /* the risk the team chose to leave open */\n  crate:{wet:false, moved:false},\n  bags:3,                /* rescue bags on the board */\n  bonusPrep:false,       /* earned in the jungle, spent on the mountain */\n  marker:null,           /* the trail marker the team set */\n  backup:null,           /* last confirmed point, if they prepared one */\n  shelter:false,\n  route:null, routeConfirmed:null, expect:\"\", sign:\"\",\n  readback:\"none\",       /* none | general | wrong | correct */\n  log:[]                 /* one line per recorded event */\n};\nfunction runLog(stage,text,who){\n  RUN.log.push({stage:stage,text:text,who:who||null});\n}\nfunction runOnce(key){            /* an effect may only land once per session */\n  RUN._once=RUN._once||{};\n  if(RUN._once[key])return false;\n  RUN._once[key]=true; return true;\n}\nfunction evShare(id,by,text){\n  if(RUN.evidence[id])return false;\n  RUN.evidence[id]={by:by,text:text};\n  runLog(RUN.stage,\"Evidence shared: \"+text,by);\n  return true;\n}\nfunction evCount(){return Object.keys(RUN.evidence).length;}\n/* ---------------- storyboard asset table (A01..A21) ----------------\n   Scenes are full frames. Everything with an underscore is one cut-out layer\n   from the matching atlas, so a decision can swap a single element inside a\n   frame instead of replacing the whole picture. */\nconst SB={\n  camp:\"data:image/webp;base64,\", campRain:\"data:image/webp;base64,\", jungleOut:\"data:image/webp;base64,\",\n  mtnOut:\"data:image/webp;base64,\", desertIn:\"data:image/webp;base64,\", desertStorm:\"data:image/webp;base64,\", arrival:\"data:image/webp;base64,\",\n  snow:\"data:image/webp;base64,\", sand:\"data:image/webp;base64,\",\n  ev:{roofgap:\"data:image/webp;base64,\", cratewet:\"data:image/webp;base64,\",\n      seamleak:\"data:image/webp;base64,\", groundpool:\"data:image/webp;base64,\",\n      tower:\"data:image/webp;base64,\", riverbed:\"data:image/webp;base64,\",\n      crack:\"data:image/webp;base64,";
